/**
 * KPI ADAPTER LAYER
 *
 * Maps Zod-validated API responses to selector input format.
 * Keeps UI selectors decoupled from Zod schemas.
 *
 * Architecture: API (Zod) → Adapter → Selectors (Pure) → UI
 */

import type { z } from 'zod';
import type { KPIResponseSchema } from '@shared/contracts/kpi-selector.contract';
import type { FundRawData } from '@/core/types/fund';

type KPIApiResponse = z.infer<typeof KPIResponseSchema>;

/**
 * Adapts API response to selector input format
 * @param apiResponse - Zod-validated API response
 * @returns Selector-compatible raw data
 */
export function mapKpiResponseToSelectorInput(
  apiResponse: KPIApiResponse
): FundRawData {
  return {
    fundId: apiResponse.fundId,
    asOf: apiResponse.asOf,
    committed: apiResponse.committed,
    // Schema only has scalar 'called', not 'capitalCalls' array - create single-element array
    capitalCalls: [{
      date: apiResponse.asOf,
      amount: apiResponse.called,
    }],
    // Schema has 'distributions' as a number, not an array - create single-element array
    distributions: [{
      date: apiResponse.asOf,
      amount: apiResponse.distributions,
    }],
    // Schema only has scalar 'nav', not 'navSeries' array - create single-element array
    navSeries: [{
      date: apiResponse.asOf,
      value: apiResponse.nav,
    }],
    // Schema doesn't include investments array - return empty
    investments: [],
  };
}

/**
 * Type guard for API response validation
 */
export function isValidKpiResponse(
  data: unknown
): data is KPIApiResponse {
  try {
    const { KPIResponseSchema } = require('@shared/contracts/kpi-selector.contract');
    KPIResponseSchema.parse(data);
    return true;
  } catch {
    return false;
  }
}

/**
 * Reserve Engine API Client
 *
 * Type-safe client for the deterministic capital reserve allocation engine API.
 * Provides methods for calculating optimal reserve allocations, running optimizations,
 * and managing scenarios.
 *
 * Features:
 * - Full TypeScript type safety
 * - Automatic retry with exponential backoff
 * - Rate limit handling
 * - Request correlation IDs
 * - Error handling with detailed error types
 * - AbortController support for request cancellation
 */

import type {
  ReserveCalculationRequest,
  ReserveCalculationResponse,
  OptimizationRequest,
  OptimizationResponse,
  ScenarioResponse,
  ErrorResponse,
  ValidationErrorResponse,
  RateLimitResponse,
  HealthCheckResponse,
  ReserveEngineClientConfig,
  RequestOptions,
  ApiResponse,
} from '../../../shared/types/reserve-engine';

import {
  isErrorResponse,
  isValidationErrorResponse,
  isRateLimitResponse,
  assertSuccessResponse,
} from '../../../shared/types/reserve-engine';

// ============================================================================
// Error Classes
// ============================================================================

export class ReserveEngineError extends Error {
  constructor(
    message: string,
    public readonly response: ErrorResponse
  ) {
    super(message);
    this.name = 'ReserveEngineError';
  }
}

export class ValidationError extends ReserveEngineError {
  constructor(public override readonly response: ValidationErrorResponse) {
    super('Validation failed', response);
    this.name = 'ValidationError';
  }
}

export class RateLimitError extends ReserveEngineError {
  constructor(public override readonly response: RateLimitResponse) {
    super(`Rate limit exceeded. Retry after ${response.retryAfter}s`, response);
    this.name = 'RateLimitError';
  }
}

export class AuthenticationError extends ReserveEngineError {
  constructor(response: ErrorResponse) {
    super('Authentication failed', response);
    this.name = 'AuthenticationError';
  }
}

export class NotFoundError extends ReserveEngineError {
  constructor(response: ErrorResponse) {
    super('Resource not found', response);
    this.name = 'NotFoundError';
  }
}

// ============================================================================
// Client Implementation
// ============================================================================

export class ReserveEngineClient {
  private readonly config: Required<
    Omit<ReserveEngineClientConfig, 'apiKey' | 'onError' | 'onRateLimit'>
  > & {
    apiKey?: string;
    onError?: (error: ErrorResponse) => void;
    onRateLimit?: (response: RateLimitResponse) => void;
  };

  constructor(config: ReserveEngineClientConfig) {
    this.config = {
      baseUrl: config.baseUrl,
      ...(config.apiKey !== undefined ? { apiKey: config.apiKey } : {}),
      timeout: config.timeout ?? 30000,
      retryAttempts: config.retryAttempts ?? 3,
      retryDelay: config.retryDelay ?? 1000,
      ...(config.onError !== undefined ? { onError: config.onError } : {}),
      ...(config.onRateLimit !== undefined ? { onRateLimit: config.onRateLimit } : {}),
    };
  }

  // ==========================================================================
  // Public API Methods
  // ==========================================================================

  /**
   * Calculate optimal reserve allocation
   *
   * @param request - Reserve calculation request parameters
   * @param options - Request options (timeout, signal, headers)
   * @returns Allocation result with initial deals, capital breakdown, and stage details
   * @throws {ValidationError} If request validation fails
   * @throws {RateLimitError} If rate limit is exceeded
   * @throws {ReserveEngineError} For other API errors
   */
  async calculateReserveAllocation(
    request: ReserveCalculationRequest,
    options?: RequestOptions
  ): Promise<ReserveCalculationResponse> {
    const response = await this.post<ReserveCalculationResponse>(
      '/reserve/calculate',
      request,
      options
    );

    assertSuccessResponse(response);
    return response;
  }

  /**
   * Optimize portfolio allocation across multiple scenarios
   *
   * @param request - Optimization request with constraints and goals
   * @param options - Request options
   * @returns Optimal scenario and comparison of all scenarios
   * @throws {ValidationError} If request validation fails
   * @throws {RateLimitError} If rate limit is exceeded
   * @throws {ReserveEngineError} For other API errors
   */
  async optimizeReserveAllocation(
    request: OptimizationRequest,
    options?: RequestOptions
  ): Promise<OptimizationResponse> {
    const response = await this.post<OptimizationResponse>(
      '/reserve/optimize',
      request,
      options
    );

    assertSuccessResponse(response);
    return response;
  }

  /**
   * Get scenario results by ID
   *
   * @param scenarioId - Unique scenario identifier
   * @param options - Request options
   * @returns Scenario calculation results
   * @throws {NotFoundError} If scenario is not found
   * @throws {ReserveEngineError} For other API errors
   */
  async getScenario(
    scenarioId: string,
    options?: RequestOptions
  ): Promise<ScenarioResponse> {
    const response = await this.get<ScenarioResponse>(
      `/reserve/scenarios/${scenarioId}`,
      options
    );

    assertSuccessResponse(response);
    return response;
  }

  /**
   * Health check endpoint
   *
   * @returns Service health status
   */
  async healthCheck(): Promise<HealthCheckResponse> {
    const url = `${this.config.baseUrl}/reserve/health`;

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: this.buildHeaders(),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`Health check failed: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }

  // ==========================================================================
  // Private HTTP Methods
  // ==========================================================================

  private async get<T>(
    path: string,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path, undefined, options);
  }

  private async post<T>(
    path: string,
    body: unknown,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    return this.request<T>('POST', path, body, options);
  }

  private async request<T>(
    method: 'GET' | 'POST' | 'PUT' | 'DELETE',
    path: string,
    body?: unknown,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    const url = `${this.config.baseUrl}${path}`;
    const timeout = options?.timeout ?? this.config.timeout;

    let lastError: Error | undefined;

    for (let attempt = 0; attempt <= this.config.retryAttempts; attempt++) {
      try {
        const controller = new AbortController();
        const signal = options?.signal ?? controller.signal;

        const timeoutId = setTimeout(() => controller.abort(), timeout);

        const fetchOptions: RequestInit = {
          method,
          headers: this.buildHeaders(options?.headers),
          signal,
        };

        if (body !== undefined) {
          fetchOptions.body = JSON.stringify(body);
        }

        const response = await fetch(url, fetchOptions);

        clearTimeout(timeoutId);

        const data = await response.json();

        // Handle error responses
        if (!response.ok) {
          return this.handleErrorResponse(response.status, data);
        }

        return data as ApiResponse<T>;
      } catch (error) {
        lastError = error as Error;

        // Don't retry on abort
        if ((error as Error).name === 'AbortError') {
          throw error;
        }

        // Don't retry on last attempt
        if (attempt === this.config.retryAttempts) {
          break;
        }

        // Exponential backoff
        const delay = this.config.retryDelay * Math.pow(2, attempt);
        await this.sleep(delay);
      }
    }

    throw lastError ?? new Error('Request failed after all retry attempts');
  }

  // ==========================================================================
  // Helper Methods
  // ==========================================================================

  private buildHeaders(customHeaders?: Record<string, string>): HeadersInit {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'X-Client-Version': '1.0.0',
      ...customHeaders,
    };

    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    return headers;
  }

  private handleErrorResponse(status: number, data: unknown): ErrorResponse {
    if (!isErrorResponse(data)) {
      // Construct error response from non-standard error
      const errorResponse: ErrorResponse = {
        success: false,
        error: 'Unknown error',
        code: 'UNKNOWN_ERROR',
        correlationId: 'unknown',
        timestamp: new Date().toISOString(),
      };

      this.config.onError?.(errorResponse);
      return errorResponse;
    }

    // Handle specific error types
    if (isValidationErrorResponse(data)) {
      const error = new ValidationError(data);
      this.config.onError?.(data);
      throw error;
    }

    if (isRateLimitResponse(data)) {
      const error = new RateLimitError(data);
      this.config.onRateLimit?.(data);
      throw error;
    }

    if (status === 401) {
      const error = new AuthenticationError(data);
      this.config.onError?.(data);
      throw error;
    }

    if (status === 404) {
      const error = new NotFoundError(data);
      this.config.onError?.(data);
      throw error;
    }

    // Generic error response
    const error = new ReserveEngineError(data.error, data);
    this.config.onError?.(data);
    throw error;
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a Reserve Engine API client
 *
 * @param config - Client configuration
 * @returns Configured client instance
 */
export function createReserveEngineClient(
  config: ReserveEngineClientConfig
): ReserveEngineClient {
  return new ReserveEngineClient(config);
}

/**
 * Create a Reserve Engine API client with default configuration
 *
 * @param apiKey - API authentication key
 * @param baseUrl - Optional base URL (defaults to current host)
 * @returns Configured client instance
 */
export function createDefaultClient(
  apiKey: string,
  baseUrl?: string
): ReserveEngineClient {
  return new ReserveEngineClient({
    baseUrl: baseUrl ?? `${window.location.origin}/api/v1`,
    apiKey,
    timeout: 30000,
    retryAttempts: 3,
    retryDelay: 1000,
  });
}

// ============================================================================
// React Hook (Optional)
// ============================================================================

/**
 * React hook for using the Reserve Engine client
 *
 * Usage:
 * ```tsx
 * const client = useReserveEngineClient(apiKey);
 * const result = await client.calculateReserveAllocation(request);
 * ```
 */
export function useReserveEngineClient(
  apiKey: string,
  baseUrl?: string
): ReserveEngineClient {
  // In a real implementation, use useMemo to prevent recreation on every render
  return createDefaultClient(apiKey, baseUrl);
}

// ============================================================================
// Re-exports from shared types
// ============================================================================

export type * from '../../../shared/types/reserve-engine';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Alert, AlertDescription } from '@/components/ui/alert';
import {
  CheckCircle,
  AlertTriangle,
  XCircle,
  RefreshCw,
  Terminal,
  Database,
  GitBranch,
  TestTube,
  Zap,
  Activity,
  Wrench,
  TrendingUp,
  TrendingDown,
  Minus
} from 'lucide-react';

interface DevHealthMetrics {
  typescript: {
    errorCount: number;
    errors: Array<{ file: string; line: number; message: string }>;
    trend: 'improving' | 'stable' | 'degrading';
  };
  tests: {
    status: 'passing' | 'failing' | 'unknown';
    passCount: number;
    failCount: number;
    coverage: number;
    performance: {
      avgDuration: number;
      slowTests: Array<{ name: string; duration: number }>;
    };
  };
  build: {
    status: 'success' | 'failed' | 'building';
    duration: number;
    size: {
      client: number;
      server: number;
    };
    warnings: number;
  };
  monteCarlo: {
    status: 'healthy' | 'degraded' | 'offline';
    avgLatency: number;
    throughput: number;
    errorRate: number;
  };
  database: {
    status: 'connected' | 'disconnected' | 'degraded';
    latency: number;
    connectionCount: number;
  };
  devServer: {
    status: 'running' | 'stopped' | 'error';
    port: number;
    memory: number;
    uptime: number;
  };
  git: {
    branch: string;
    uncommittedChanges: number;
    lastCommit: {
      hash: string;
      message: string;
      timestamp: string;
    };
  };
}

interface DashboardData {
  timestamp: string;
  overall: 'healthy' | 'warning' | 'critical';
  metrics: DevHealthMetrics;
}

const DevDashboard: React.FC = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());

  const fetchHealth = useCallback(async () => {
    try {
      const response = await fetch('/api/dev-dashboard/health');
      if (!response.ok) throw new Error('Failed to fetch health data');
      const newData = await response.json();
      setData(newData);
      setError(null);
      setLastUpdated(new Date());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  }, []);

  const handleQuickFix = async (action: string) => {
    try {
      const response = await fetch(`/api/dev-dashboard/fix/${action}`, {
        method: 'POST'
      });
      const result = await response.json();

      if (result.success) {
        // Refresh data after successful fix
        await fetchHealth();
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fix failed');
    }
  };

  useEffect(() => {
    fetchHealth();
    const interval = setInterval(fetchHealth, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, [fetchHealth]);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'passing':
      case 'success':
      case 'healthy':
      case 'connected':
      case 'running':
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'warning':
      case 'degraded':
        return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case 'failing':
      case 'failed':
      case 'critical':
      case 'offline':
      case 'disconnected':
      case 'stopped':
      case 'error':
        return <XCircle className="h-4 w-4 text-red-500" />;
      default:
        return <Minus className="h-4 w-4 text-gray-500" />;
    }
  };

  const getTrendIcon = (trend: string) => {
    switch (trend) {
      case 'improving':
        return <TrendingUp className="h-3 w-3 text-green-500" />;
      case 'degrading':
        return <TrendingDown className="h-3 w-3 text-red-500" />;
      default:
        return <Minus className="h-3 w-3 text-gray-500" />;
    }
  };

  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))  } ${  sizes[i]}`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="h-8 w-8 animate-spin" />
        <span className="ml-2">Loading dashboard...</span>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Alert className="mx-4">
        <AlertTriangle className="h-4 w-4" />
        <AlertDescription>
          {error || 'Failed to load dashboard data'}
          <Button
            variant="outline"
            size="sm"
            className="ml-4"
            onClick={fetchHealth}
          >
            Retry
          </Button>
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Development Dashboard</h1>
          <p className="text-muted-foreground">
            Last updated: {lastUpdated.toLocaleTimeString()}
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <Badge
            variant={
              data.overall === 'healthy' ? 'default' :
              data.overall === 'warning' ? 'secondary' : 'destructive'
            }
            className="text-sm px-3 py-1"
          >
            {getStatusIcon(data.overall)}
            <span className="ml-2 capitalize">{data.overall}</span>
          </Badge>
          <Button variant="outline" size="sm" onClick={fetchHealth}>
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh
          </Button>
        </div>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

        {/* TypeScript Health */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">TypeScript</CardTitle>
            <div className="flex items-center space-x-1">
              {getTrendIcon(data.metrics.typescript.trend)}
              {getStatusIcon(data.metrics.typescript.errorCount === 0 ? 'success' : 'failed')}
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {data.metrics.typescript.errorCount}
            </div>
            <p className="text-xs text-muted-foreground">
              {data.metrics.typescript.errorCount === 0 ? 'No errors' : 'Type errors'}
            </p>
            {data.metrics.typescript.errorCount > 0 && (
              <div className="mt-4">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleQuickFix('typescript')}
                  className="w-full"
                >
                  <Wrench className="h-4 w-4 mr-2" />
                  Quick Fix
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Test Suite */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Test Suite</CardTitle>
            <div className="flex items-center space-x-1">
              <TestTube className="h-4 w-4" />
              {getStatusIcon(data.metrics.tests.status)}
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {data.metrics.tests.passCount}
            </div>
            <p className="text-xs text-muted-foreground">
              passing {data.metrics.tests.failCount > 0 && `, ${data.metrics.tests.failCount} failing`}
            </p>
            <div className="mt-2">
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>Coverage</span>
                <span>{data.metrics.tests.coverage}%</span>
              </div>
              <Progress value={data.metrics.tests.coverage} className="mt-1" />
            </div>
            {data.metrics.tests.status !== 'passing' && (
              <div className="mt-4">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleQuickFix('tests')}
                  className="w-full"
                >
                  <Terminal className="h-4 w-4 mr-2" />
                  Run Tests
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Build Status */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Build</CardTitle>
            {getStatusIcon(data.metrics.build.status)}
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {data.metrics.build.duration / 1000}s
            </div>
            <p className="text-xs text-muted-foreground">
              last build time
            </p>
            <div className="mt-2 space-y-1">
              <div className="flex justify-between text-xs">
                <span>Client:</span>
                <span>{formatBytes(data.metrics.build.size.client)}</span>
              </div>
              <div className="flex justify-between text-xs">
                <span>Server:</span>
                <span>{formatBytes(data.metrics.build.size.server)}</span>
              </div>
            </div>
            {data.metrics.build.status !== 'success' && (
              <div className="mt-4">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleQuickFix('build')}
                  className="w-full"
                >
                  <Zap className="h-4 w-4 mr-2" />
                  Rebuild
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Monte Carlo Performance */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Monte Carlo</CardTitle>
            <div className="flex items-center space-x-1">
              <Activity className="h-4 w-4" />
              {getStatusIcon(data.metrics.monteCarlo.status)}
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {data.metrics.monteCarlo.avgLatency}ms
            </div>
            <p className="text-xs text-muted-foreground">
              avg latency
            </p>
            <div className="mt-2 space-y-1">
              <div className="flex justify-between text-xs">
                <span>Throughput:</span>
                <span>{data.metrics.monteCarlo.throughput}/min</span>
              </div>
              <div className="flex justify-between text-xs">
                <span>Error Rate:</span>
                <span>{(data.metrics.monteCarlo.errorRate * 100).toFixed(1)}%</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Database */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Database</CardTitle>
            <div className="flex items-center space-x-1">
              <Database className="h-4 w-4" />
              {getStatusIcon(data.metrics.database.status)}
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {data.metrics.database.latency}ms
            </div>
            <p className="text-xs text-muted-foreground">
              connection latency
            </p>
            <div className="mt-2">
              <div className="flex justify-between text-xs">
                <span>Connections:</span>
                <span>{data.metrics.database.connectionCount}</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Dev Server */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Dev Server</CardTitle>
            {getStatusIcon(data.metrics.devServer.status)}
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              :{data.metrics.devServer.port}
            </div>
            <p className="text-xs text-muted-foreground">
              port
            </p>
            <div className="mt-2 space-y-1">
              <div className="flex justify-between text-xs">
                <span>Memory:</span>
