/**
 * Coverage Indicator Component
 *
 * Displays data coverage metrics for cohort analysis.
 * Shows mapping coverage percentage with V2 threshold indicator.
 */

import { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { CheckCircle, AlertTriangle, Info, XCircle } from 'lucide-react';
import type { CoverageSummaryType } from '@shared/types';

interface CoverageIndicatorProps {
  /** Coverage data */
  coverage: CoverageSummaryType;
  /** Whether this is for the entire analysis or a specific cohort */
  scope?: 'analysis' | 'cohort';
  /** Compact mode for inline display */
  compact?: boolean;
}

const V2_THRESHOLD = 0.9; // 90% coverage required for V2 mode

/**
 * Gets the status color based on coverage percentage
 */
function getCoverageStatus(percentage: number): {
  color: string;
  icon: typeof CheckCircle;
  label: string;
} {
  if (percentage >= V2_THRESHOLD) {
    return { color: 'text-green-600', icon: CheckCircle, label: 'V2 Ready' };
  }
  if (percentage >= 0.7) {
    return { color: 'text-yellow-600', icon: AlertTriangle, label: 'Partial' };
  }
  if (percentage >= 0.5) {
    return { color: 'text-orange-600', icon: AlertTriangle, label: 'Limited' };
  }
  return { color: 'text-red-600', icon: XCircle, label: 'Low' };
}

export function CoverageIndicator({
  coverage,
  scope = 'analysis',
  compact = false,
}: CoverageIndicatorProps) {
  const overallCoverage = coverage.overallPct;
  const status = getCoverageStatus(overallCoverage);
  const StatusIcon = status.icon;

  // Calculate lowest coverage category for display
  const lowestCategory = useMemo(() => {
    const categories = [
      { name: 'Paid-In', pct: coverage.paidInPct },
      { name: 'Distributions', pct: coverage.distributionsPct },
      { name: 'Vintage', pct: coverage.vintagePct },
    ];
    if (coverage.marksPct !== undefined) {
      categories.push({ name: 'Marks', pct: coverage.marksPct });
    }
    return categories.sort((a, b) => a.pct - b.pct)[0];
  }, [coverage]);

  if (compact) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>
            <div className="flex items-center gap-2">
              <StatusIcon className={`h-4 w-4 ${status.color}`} />
              <span className="text-sm font-medium">
                {(overallCoverage * 100).toFixed(0)}%
              </span>
              <Badge
                variant={overallCoverage >= V2_THRESHOLD ? 'default' : 'secondary'}
                className="text-xs"
              >
                {status.label}
              </Badge>
            </div>
          </TooltipTrigger>
          <TooltipContent>
            <div className="space-y-1 text-xs">
              <div>Paid-In: {(coverage.paidInPct * 100).toFixed(1)}%</div>
              <div>Distributions: {(coverage.distributionsPct * 100).toFixed(1)}%</div>
              <div>Vintage: {(coverage.vintagePct * 100).toFixed(1)}%</div>
              {coverage.marksPct !== undefined && (
                <div>Marks: {(coverage.marksPct * 100).toFixed(1)}%</div>
              )}
            </div>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium flex items-center justify-between">
          <span className="flex items-center gap-2">
            <Info className="h-4 w-4 text-gray-400" />
            Data Coverage
          </span>
          <Badge
            variant={overallCoverage >= V2_THRESHOLD ? 'default' : 'secondary'}
          >
            {status.label}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Overall Progress */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-gray-600">Overall Coverage</span>
            <span className={`font-medium ${status.color}`}>
              {(overallCoverage * 100).toFixed(1)}%
            </span>
          </div>
          <Progress
            value={overallCoverage * 100}
            className="h-2"
          />
          {overallCoverage < V2_THRESHOLD && (
            <p className="text-xs text-gray-500">
              {((V2_THRESHOLD - overallCoverage) * 100).toFixed(1)}% more needed for
              V2 mode ({(V2_THRESHOLD * 100).toFixed(0)}% threshold)
            </p>
          )}
        </div>

        {/* Breakdown */}
        <div className="grid grid-cols-2 gap-4">
          {/* Paid-In Coverage */}
          <div className="space-y-1">
            <div className="flex items-center justify-between text-xs">
              <span className="text-gray-500">Paid-In Data</span>
              <span className="font-medium">{(coverage.paidInPct * 100).toFixed(0)}%</span>
            </div>
            <Progress value={coverage.paidInPct * 100} className="h-1" />
          </div>

          {/* Distributions Coverage */}
          <div className="space-y-1">
            <div className="flex items-center justify-between text-xs">
              <span className="text-gray-500">Distributions</span>
              <span className="font-medium">{(coverage.distributionsPct * 100).toFixed(0)}%</span>
            </div>
            <Progress value={coverage.distributionsPct * 100} className="h-1" />
          </div>

          {/* Vintage Coverage */}
          <div className="space-y-1">
            <div className="flex items-center justify-between text-xs">
              <span className="text-gray-500">Vintage Data</span>
              <span className="font-medium">{(coverage.vintagePct * 100).toFixed(0)}%</span>
            </div>
            <Progress value={coverage.vintagePct * 100} className="h-1" />
          </div>

          {/* Marks Coverage (if available) */}
          {coverage.marksPct !== undefined && (
            <div className="space-y-1">
              <div className="flex items-center justify-between text-xs">
                <span className="text-gray-500">Marks Data</span>
                <span className="font-medium">{(coverage.marksPct * 100).toFixed(0)}%</span>
              </div>
              <Progress value={coverage.marksPct * 100} className="h-1" />
            </div>
          )}
        </div>

        {/* Warning for lowest category */}
        {lowestCategory && lowestCategory.pct < 0.9 && (
          <div className="pt-2 border-t border-gray-100">
            <div className="flex items-center gap-2 text-xs text-amber-600">
              <AlertTriangle className="h-3 w-3" />
              {lowestCategory.name} coverage is only {(lowestCategory.pct * 100).toFixed(0)}%
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * Simple inline coverage badge
 */
export function CoverageBadge({
  coverage,
}: {
  coverage: CoverageSummaryType;
}) {
  const overall = coverage.overallPct;
  const status = getCoverageStatus(overall);

  return (
    <Badge
      variant={overall >= V2_THRESHOLD ? 'default' : 'outline'}
      className="text-xs"
    >
      {(overall * 100).toFixed(0)}% coverage
    </Badge>
  );
}

export default CoverageIndicator;

import React from 'react';

type ToastType = 'success' | 'error' | 'info';
type Toast = { id: string; type: ToastType; message: string; at: number; ttl: number };

const MAX_TOASTS = 3;
const DEFAULT_TTL = 3000;
const bus = new EventTarget();

export function pushToast(message: string, type: ToastType = 'info', ttl = DEFAULT_TTL) {
  bus.dispatchEvent(new CustomEvent('toast:add', { detail: { message, type, ttl } }));
}
export const toastSuccess = (m: string) => pushToast(m, 'success');
export const toastError = (m: string) => pushToast(m, 'error');
export const toastInfo = (m: string) => pushToast(m, 'info');

export function ToastViewport() {
  const [toasts, setToasts] = React.useState<Toast[]>([]);

  React.useEffect(() => {
    function onAdd(e: Event) {
      const { message, type, ttl } = (e as CustomEvent).detail as { message: string; type: ToastType; ttl: number };
      const t: Toast = { id: Math.random().toString(36).slice(2), type, message, at: Date.now(), ttl };
      setToasts((prev) => {
        const next = [...prev, t];
        return next.length > MAX_TOASTS ? next.slice(next.length - MAX_TOASTS) : next;
      });
      setTimeout(() => setToasts((prev) => prev.filter((x) => x.id !== t.id)), ttl);
    }
    bus.addEventListener('toast:add', onAdd as any);
    return () => bus.removeEventListener('toast:add', onAdd as any);
  }, []);

  if (!toasts.length) return null;
  return (
    <div aria-live="polite" aria-atomic="true" role="status"
         style={{ position:'fixed', right:16, top:16, display:'flex', flexDirection:'column', gap:8, zIndex:9999 }}>
      {toasts.map((t) => (
        <div key={t.id}
             style={{
               minWidth:260, maxWidth:420, padding:'10px 12px', borderRadius:8,
               color:'#111', background: t.type==='error' ? '#fecaca' : t.type==='success' ? '#bbf7d0' : '#e5e7eb',
               border:'1px solid rgba(0,0,0,.08)', boxShadow:'0 8px 20px rgba(0,0,0,.08)'
             }}>
          <strong style={{marginRight:6}}>
            {t.type === 'error' ? 'Error' : t.type === 'success' ? 'Saved' : 'Notice'}:
          </strong>
          <span>{t.message}</span>
        </div>
      ))}
    </div>
  );
}

/**
 * Comparison Delta Table Component
 *
 * Displays scenario comparison results in a tabular format with delta highlighting.
 * Shows metrics for each scenario with absolute and percentage differences from baseline.
 */

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { ArrowUp, ArrowDown, Minus } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { DeltaMetric, ScenarioSnapshot } from '@shared/types/scenario-comparison';

interface ComparisonDeltaTableProps {
  deltaMetrics: DeltaMetric[];
  scenarios: ScenarioSnapshot[];
  showAbsolute?: boolean;
  showPercentage?: boolean;
  highlightThreshold?: number;
  colorScheme?: 'traffic_light' | 'heatmap' | 'grayscale';
}

const formatValue = (value: number, metricName: string): string => {
  if (metricName === 'moic' || metricName.includes('multiple')) {
    return `${value.toFixed(2)}x`;
  }
  if (metricName === 'irr' || metricName.includes('irr')) {
    return `${(value * 100).toFixed(1)}%`;
  }
  if (value >= 1_000_000) {
    return `$${(value / 1_000_000).toFixed(1)}M`;
  }
  if (value >= 1_000) {
    return `$${(value / 1_000).toFixed(0)}K`;
  }
  return value.toFixed(2);
};

const formatDelta = (delta: number, metricName: string, isPercentage: boolean): string => {
  const sign = delta >= 0 ? '+' : '';
  if (isPercentage) {
    return `${sign}${delta.toFixed(1)}%`;
  }
  if (metricName === 'moic' || metricName.includes('multiple')) {
    return `${sign}${delta.toFixed(2)}x`;
  }
  if (metricName === 'irr' || metricName.includes('irr')) {
    return `${sign}${(delta * 100).toFixed(1)}%`;
  }
  if (Math.abs(delta) >= 1_000_000) {
    return `${sign}$${(delta / 1_000_000).toFixed(1)}M`;
  }
  if (Math.abs(delta) >= 1_000) {
    return `${sign}$${(delta / 1_000).toFixed(0)}K`;
  }
  return `${sign}${delta.toFixed(2)}`;
};

const getDeltaColor = (
  isBetter: boolean,
  isSignificant: boolean,
  colorScheme: string
): string => {
  if (!isSignificant) return 'text-gray-500';

  if (colorScheme === 'grayscale') {
    return isBetter ? 'text-gray-900 font-semibold' : 'text-gray-600';
  }

  if (colorScheme === 'heatmap') {
    return isBetter ? 'text-blue-600' : 'text-orange-600';
  }

  // traffic_light (default)
  return isBetter ? 'text-green-600' : 'text-red-600';
};

const DeltaIndicator: React.FC<{
  delta: number;
  isBetter: boolean;
  isSignificant: boolean;
}> = ({ delta, isBetter, isSignificant }) => {
  if (!isSignificant || delta === 0) {
    return <Minus className="w-3 h-3 text-gray-400" />;
  }

  const Icon = delta > 0 ? ArrowUp : ArrowDown;
  const color = isBetter ? 'text-green-500' : 'text-red-500';

  return <Icon className={cn('w-3 h-3', color)} />;
};

export function ComparisonDeltaTable({
  deltaMetrics,
  scenarios,
  showAbsolute = true,
  showPercentage = true,
  highlightThreshold = 0.1,
  colorScheme = 'traffic_light',
}: ComparisonDeltaTableProps) {
  // Group metrics by metric name
  const metricsByName = deltaMetrics.reduce<Record<string, DeltaMetric[]>>(
    (acc, metric) => {
      const existing = acc[metric.metricName];
      if (!existing) {
        acc[metric.metricName] = [metric];
      } else {
        existing.push(metric);
      }
      return acc;
    },
    {}
  );

  const baseScenario = scenarios.find((s) => s.isBase);
  const comparisonScenarios = scenarios.filter((s) => !s.isBase);

  if (!baseScenario || comparisonScenarios.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-gray-500">
          No comparison data available
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          Metric Comparison
          <Badge variant="outline" className="text-xs font-normal">
            Base: {baseScenario.name}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-40">Metric</TableHead>
                <TableHead className="text-right">Base Value</TableHead>
                {comparisonScenarios.map((scenario) => (
                  <TableHead key={scenario.id} className="text-right">
                    <div className="flex flex-col items-end">
                      <span>{scenario.name}</span>
                      <span className="text-xs text-gray-400 font-normal">
                        vs Base
                      </span>
                    </div>
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>
            <TableBody>
              {Object.entries(metricsByName).map(([metricName, metrics]) => {
                const firstMetric = metrics[0];
                const baseValue = firstMetric?.baseValue ?? 0;
                const isSignificant =
                  Math.abs(firstMetric?.percentageDelta ?? 0) / 100 >=
                  highlightThreshold;

                return (
                  <TableRow key={metricName}>
                    <TableCell className="font-medium">
                      {firstMetric?.displayName || metricName}
                    </TableCell>
                    <TableCell className="text-right font-mono">
                      {formatValue(baseValue, metricName)}
                    </TableCell>
                    {comparisonScenarios.map((scenario) => {
                      const metric = metrics.find(
                        (m) => m.scenarioId === scenario.id
                      );
                      if (!metric) {
                        return (
                          <TableCell key={scenario.id} className="text-right">
                            -
                          </TableCell>
                        );
                      }

                      const metricIsSignificant =
                        Math.abs(metric.percentageDelta ?? 0) / 100 >=
                        highlightThreshold;

                      return (
                        <TableCell key={scenario.id} className="text-right">
                          <div className="flex flex-col items-end gap-1">
                            <span className="font-mono">
                              {formatValue(metric.comparisonValue, metricName)}
                            </span>
                            <div className="flex items-center gap-1 text-sm">
                              <DeltaIndicator
                                delta={metric.absoluteDelta}
                                isBetter={metric.isBetter}
                                isSignificant={metricIsSignificant}
                              />
                              <span
                                className={getDeltaColor(
                                  metric.isBetter,
                                  metricIsSignificant,
                                  colorScheme
                                )}
                              >
                                {showAbsolute && (
                                  <span>
                                    {formatDelta(
                                      metric.absoluteDelta,
                                      metricName,
                                      false
                                    )}
                                  </span>
                                )}
                                {showAbsolute && showPercentage && ' '}
                                {showPercentage && metric.percentageDelta !== null && (
                                  <span className="text-xs">
                                    ({formatDelta(metric.percentageDelta, metricName, true)})
                                  </span>
                                )}
                              </span>
                            </div>
                          </div>
                        </TableCell>
                      );
                    })}
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  );
}

export default ComparisonDeltaTable;

/**
