import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { Plus, Trash2, Edit } from 'lucide-react';

export interface CustomField {
  id: string;
  name: string;
  type: 'number' | 'tags' | 'text' | 'color' | 'date';
  required?: boolean;
  options?: string[]; // For tags and color options
  defaultValue?: any;
}

interface CustomFieldsManagerProps {
  fields: CustomField[];
  onFieldsChange: (_fields: CustomField[]) => void;
  className?: string;
}

const FIELD_TYPE_OPTIONS = [
  { value: 'number', label: 'Number' },
  { value: 'tags', label: 'Tags' },
  { value: 'text', label: 'Text' },
  { value: 'color', label: 'Color Codes' },
  { value: 'date', label: 'Dates' },
];

const COLOR_PRESETS = [
  '#ef4444', '#f97316', '#f59e0b', '#eab308', '#84cc16',
  '#22c55e', '#10b981', '#14b8a6', '#06b6d4', '#0ea5e9',
  '#3b82f6', '#6366f1', '#8b5cf6', '#a855f7', '#d946ef',
  '#ec4899', '#f43f5e', '#64748b', '#374151', '#1f2937'
];

export default function CustomFieldsManager({ fields, onFieldsChange, className = '' }: CustomFieldsManagerProps) {
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [editingField, setEditingField] = useState<CustomField | null>(null);
  const [newField, setNewField] = useState<Partial<CustomField>>({
    name: '',
    type: 'text',
    required: false,
  });

  const handleAddField = () => {
    if (!newField.name || !newField.type) return;

    const field: CustomField = {
      id: `field-${Date.now()}`,
      name: newField.name,
      type: newField.type as CustomField['type'],
      required: newField.required || false,
      ...(newField.type === 'color' ? { options: COLOR_PRESETS } : {}),
    };

    onFieldsChange([...fields, field]);
    setNewField({ name: '', type: 'text', required: false });
    setIsAddDialogOpen(false);
  };

  const handleEditField = (field: CustomField) => {
    setEditingField(field);
    setNewField({ ...field });
    setIsAddDialogOpen(true);
  };

  const handleUpdateField = () => {
    if (!editingField || !newField.name || !newField.type) return;

    const updatedFields = fields.map(f => 
      f.id === editingField.id 
        ? { ...f, name: newField.name!, type: newField.type as CustomField['type'], required: newField.required || false }
        : f
    );

    onFieldsChange(updatedFields);
    setNewField({ name: '', type: 'text', required: false });
    setEditingField(null);
    setIsAddDialogOpen(false);
  };

  const handleDeleteField = (fieldId: string) => {
    onFieldsChange(fields.filter(f => f.id !== fieldId));
  };

  const getFieldTypeColor = (type: string) => {
    switch (type) {
      case 'number': return 'bg-blue-100 text-blue-800';
      case 'tags': return 'bg-green-100 text-green-800';
      case 'text': return 'bg-gray-100 text-gray-800';
      case 'color': return 'bg-purple-100 text-purple-800';
      case 'date': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold">Custom Fields Definitions</h2>
          <p className="text-sm text-gray-600 mt-1">
            Custom Fields are used to add additional information to an investment. For example, you may want to add additional tags to an investment to help you filter and sort your investments, or create a color field to help you visually identify investments.
          </p>
        </div>
        <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
          <DialogTrigger asChild>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              Add Field
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-md">
            <DialogHeader>
              <DialogTitle>
                {editingField ? 'Edit Custom Field' : 'Add Custom Field'}
              </DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="field-name">Field Name</Label>
                <Input
                  id="field-name"
                  value={newField.name || ''}
                  onChange={(e: any) => setNewField({ ...newField, name: e.target.value })}
                  placeholder="e.g., Internal Status"
                />
              </div>
              <div>
                <Label htmlFor="field-type">Field Type</Label>
                <Select
                  value={newField.type || 'text'}
                  onValueChange={(value: any) => setNewField({ ...newField, type: value as CustomField['type'] })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {FIELD_TYPE_OPTIONS.map(option => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex justify-end space-x-2">
                <Button variant="outline" onClick={() => {
                  setIsAddDialogOpen(false);
                  setEditingField(null);
                  setNewField({ name: '', type: 'text', required: false });
                }}>
                  Cancel
                </Button>
                <Button onClick={editingField ? handleUpdateField : handleAddField}>
                  {editingField ? 'Update' : 'Add Field'}
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {/* Fields List */}
      <Card>
        <CardContent className="p-6">
          {fields.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <p>No custom fields defined yet.</p>
              <p className="text-sm">Click "Add Field" to create your first custom field.</p>
            </div>
          ) : (
            <div className="space-y-4">
              {fields.map((field: any) => (
                <div key={field.id} className="flex items-center justify-between p-4 border rounded-lg bg-gray-50">
                  <div className="flex items-center space-x-4">
                    <div>
                      <div className="font-medium text-gray-900">{field.name}</div>
                      <Badge className={getFieldTypeColor(field.type)}>
                        {FIELD_TYPE_OPTIONS.find(opt => opt.value === field.type)?.label}
                      </Badge>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleEditField(field)}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleDeleteField(field.id)}
                      className="text-red-600 hover:text-red-800"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Preview */}
      {fields.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Preview</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              <p className="text-sm text-gray-600">
                These fields will appear in the Custom Fields section when editing investments:
              </p>
              <div className="border rounded-lg p-4 bg-gray-50">
                <h4 className="font-medium mb-3">Custom Fields</h4>
                <div className="space-y-3">
                  {fields.map((field: any) => (
                    <div key={field.id} className="flex items-center justify-between">
                      <span className="text-sm font-medium text-gray-700">{field.name}</span>
                      <div className="flex items-center space-x-2">
                        {field.type === 'color' && (
                          <div className="w-4 h-4 bg-green-500 rounded-full"></div>
                        )}
                        <Badge variant="outline" className="text-xs">
                          {FIELD_TYPE_OPTIONS.find(opt => opt.value === field.type)?.label}
                        </Badge>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  BarChart,
  Bar,
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { LazyResponsiveContainer as ResponsiveContainer } from '@/components/charts/LazyResponsiveContainer';
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  AlertTriangle,
  ArrowUpRight,
  Clock,
  Target,
  Activity,
  RefreshCw,
  Download,
  Zap
} from "lucide-react";
import { useLiquidityAnalytics, useLiquidityAlerts, useLiquidityMetrics } from '@/hooks/useLiquidityAnalytics';
import { useFundContext } from '@/contexts/FundContext';

interface CashflowDashboardProps {
  fundId: string;
  className?: string;
}

export default function CashflowDashboard({ fundId, className = '' }: CashflowDashboardProps) {
  const [timeframe, setTimeframe] = useState('12m');
  const [activeView, setActiveView] = useState('overview');

  // Get fund data from context
  const { currentFund } = useFundContext();
  const fundSize = currentFund?.size ? currentFund.size / 1000000 : 100; // Convert to millions, default to $100M

  // Use liquidity analytics hook
  const analytics = useLiquidityAnalytics({
    fundId,
    fundSize: fundSize * 1000000, // Convert to actual dollar amount
    autoRefresh: true,
    refreshIntervalMs: 30000, // 30 seconds
    defaultForecastMonths: timeframe === '6m' ? 6 : timeframe === '12m' ? 12 : 24,
    enableRealTimeAlerts: true,
  });

  // Use additional hooks
  const { alerts } = useLiquidityAlerts(
    analytics.liquidityForecast ? {
      fundId,
      asOfDate: new Date(),
      bankAccounts: [],
      totalCash: analytics.liquidityForecast.openingCash,
      totalCommitted: analytics.liquidityForecast.openingCommitted,
      totalDeployed: fundSize * 1000000 - analytics.liquidityForecast.openingCommitted,
      availableLiquidity: analytics.liquidityForecast.openingCash,
      pendingInflows: analytics.liquidityForecast.plannedCapitalCalls + analytics.liquidityForecast.expectedDistributions,
      pendingOutflows: analytics.liquidityForecast.plannedInvestments + analytics.liquidityForecast.plannedExpenses,
      netPending: (analytics.liquidityForecast.plannedCapitalCalls + analytics.liquidityForecast.expectedDistributions) -
                  (analytics.liquidityForecast.plannedInvestments + analytics.liquidityForecast.plannedExpenses),
      dryPowder: analytics.liquidityForecast.openingCash * 0.8,
      reserveRequirement: fundSize * 1000000 * 0.15,
      availableInvestment: analytics.liquidityForecast.openingCash * 0.8,
      createdAt: new Date(),
      updatedAt: new Date(),
    } : null,
    analytics.liquidityForecast
  );

  const liquidityMetrics = useLiquidityMetrics(analytics.cashFlowAnalysis);

  // Generate chart data
  const cashFlowChartData = useMemo(() => {
    if (!analytics.cashFlowAnalysis) return [];

    return analytics.cashFlowAnalysis.byMonth.map(month => ({
      month: month.month,
      inflows: month.totalInflow / 1000000, // Convert to millions
      outflows: month.totalOutflow / 1000000,
      netFlow: month.netFlow / 1000000,
    }));
  }, [analytics.cashFlowAnalysis]);

  const liquidityForecastData = useMemo(() => {
    if (!analytics.liquidityForecast) return [];

    const months = parseInt(timeframe.replace('m', ''));
    const data = [];
    const startDate = new Date();

    for (let i = 0; i <= months; i++) {
      const date = new Date(startDate);
      date.setMonth(date.getMonth() + i);

      // Simple linear projection for demonstration
      const cashDecline = (analytics.liquidityForecast.openingCash - analytics.liquidityForecast.projectedCash) / months;
      const projectedCash = analytics.liquidityForecast.openingCash - (cashDecline * i);

      data.push({
        month: date.toLocaleDateString('en-US', { month: 'short', year: '2-digit' }),
        cash: Math.max(0, projectedCash / 1000000),
        committed: (analytics.liquidityForecast.openingCommitted - (analytics.liquidityForecast.plannedCapitalCalls * i / months)) / 1000000,
      });
    }

    return data;
  }, [analytics.liquidityForecast, timeframe]);

  const expenseBreakdownData = useMemo(() => {
    if (!analytics.cashFlowAnalysis) return [];

    const expenses = Object.entries(analytics.cashFlowAnalysis.byType)
      .filter(([type, amount]) => amount < 0)
      .map(([type, amount]) => ({
        type: type.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase()),
        amount: Math.abs(amount / 1000000),
        color: getColorForExpenseType(type),
      }));

    return expenses;
  }, [analytics.cashFlowAnalysis]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 1,
    }).format(value * 1000000);
  };

  const formatCurrencyShort = (value: number) => {
    if (value >= 1) return `$${value.toFixed(1)}M`;
    return `$${(value * 1000).toFixed(0)}K`;
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Cashflow & Liquidity Management</h2>
          <p className="text-muted-foreground">Real-time liquidity monitoring and cash flow forecasting</p>
        </div>
        <div className="flex items-center gap-3">
          <Select value={timeframe} onValueChange={setTimeframe}>
            <SelectTrigger className="w-32">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="6m">6 Months</SelectItem>
              <SelectItem value="12m">12 Months</SelectItem>
              <SelectItem value="24m">24 Months</SelectItem>
            </SelectContent>
          </Select>
          <Button
            variant="outline"
            size="sm"
            onClick={analytics.refreshAll}
            disabled={analytics.isLoadingAnalysis || analytics.isLoadingForecast}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${analytics.isLoadingAnalysis || analytics.isLoadingForecast ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
          <Button variant="outline" size="sm" onClick={async () => {
            const data = await analytics.exportData();
            const blob = new Blob([data], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `cashflow-analysis-${fundId}-${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            URL.revokeObjectURL(url);
          }}>
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
        </div>
      </div>

      {/* Alerts */}
      {alerts.length > 0 && (
        <div className="space-y-2">
