                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="year" />
                  <YAxis tickFormatter={(value) => `${value.toFixed(1)}x`} />
                  <Tooltip content={<CustomTooltip />} />
                  <Legend />
                  {scenarios.map(scenario => (
