                  ))}
                </LineChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        {/* Radar Comparison */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Multi-Factor Comparison</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
