                  {scenarios.map(scenario => (
                    <Radar
                      key={scenario.id}
                      name={scenario.name}
                      dataKey={scenario.name}
                      stroke={scenario.color}
                      fill={scenario.color}
                      fillOpacity={scenario.isBaseline ? 0.3 : 0.1}
                      strokeWidth={scenario.isBaseline ? 3 : 2}
                    />
                  ))}
                  <Legend />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

