                            ranking.rank <= 6 ? 'bg-green-500' : 'bg-gray-500'}
                        `}>
                          {ranking.rank}
                        </div>
                        {ranking.rank <= 3 && (
                          <Award className="h-4 w-4 text-yellow-500" />
