export interface ButtonEnhancedProps extends ButtonProps {
  loading?: boolean;
  loadingText?: string;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  pulse?: boolean;
  confidence?: 'critical' | 'low' | 'medium' | 'high' | 'excellent';
  hapticFeedback?: boolean;
}

const ButtonEnhanced = React.forwardRef<HTMLButtonElement, ButtonEnhancedProps>(
  ({
    className,
    variant,
    size,
    asChild = false,
    loading = false,
    loadingText,
    leftIcon,
    rightIcon,
    pulse = false,
    confidence,
    hapticFeedback = false,
    children,
    onClick,
    ...props
  }, ref) => {
    // Auto-select variant based on confidence level
    const effectiveVariant = confidence
      ? (confidence === 'high' || confidence === 'excellent')
        ? 'ai-confidence-high'
        : confidence === 'medium'
        ? 'ai-confidence-medium'
        : 'ai-confidence-low'
      : variant;

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (loading || props.disabled) return;

      // Add haptic feedback simulation
      if (hapticFeedback) {
        e.currentTarget.classList.add('haptic-feedback');
        setTimeout(() => {
          e.currentTarget.classList.remove('haptic-feedback');
        }, 100);
      }

      onClick?.(e);
    };

    const Comp = asChild ? Slot : "button";

    return (
      <Button
        className={cn(
          pulse && "animate-pulse",
          className
        )}
        variant={effectiveVariant === 'ai-confidence-high' ? 'default' :
                effectiveVariant === 'ai-confidence-medium' ? 'secondary' :
                effectiveVariant === 'ai-confidence-low' ? 'outline' :
                effectiveVariant}
        size={size}
        ref={ref}
        onClick={handleClick}
        disabled={loading || props.disabled}
        aria-busy={loading}
        aria-describedby={confidence ? `confidence-${confidence}` : undefined}
        {...props}
      >
        {/* Loading spinner */}
        {loading && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-ai-thinking" />
          </div>
        )}

        {/* Button content */}
        <div className={cn(
          "flex items-center gap-2",
          loading && "invisible"
        )}>
          {leftIcon && (
