 */
export interface AnalyzeCohortInput {
  // Request parameters
  request: CohortAnalyzeRequest;

  // Cohort definition
  cohortDefinition: {
    id: string;
    fundId: number;
    name: string;
    vintageGranularity: VintageGranularity;
    sectorTaxonomyVersion: string;
    unit: CohortUnit;
  };

