/**
 * useDebounceDeep Hook
 *
 * Debounces a value with deep equality comparison to prevent unnecessary updates
 * when object/array contents haven't actually changed.
 *
 * **Use Cases:**
 * - React Hook Form watch() values (objects change identity every render)
 * - Expensive calculations triggered by form state
 * - Auto-save with object state
 *
 * **Example:**
 * ```typescript
 * const formValues = watch();
 * const debouncedFormValues = useDebounceDeep(formValues, 250);
 *
 * const calculations = useMemo(() => {
 *   return expensiveCalculation(debouncedFormValues);
 * }, [debouncedFormValues]);
 * ```
 *
 * **Performance:**
 * - Deep equality check on every render (cheap for small objects)
 * - Timer only reset if value actually changed
 * - Single timer per hook instance
 *
 * @template T - Type of value to debounce
 * @param value - The value to debounce
 * @param delay - Debounce delay in milliseconds (default: 250ms)
 * @returns Debounced value
 */

import { useState, useEffect, useRef } from 'react';

// ============================================================================
// DEEP EQUALITY UTILITY
// ============================================================================

/**
 * Deep equality comparison using JSON serialization
 *
 * **Limitations:**
 * - Functions not compared (serialized as undefined)
 * - Dates compared by ISO string
 * - Circular references not supported
 * - Property order matters in objects
 *
 * **Good enough for:**
 * - React Hook Form values (plain objects/arrays)
 * - Form state without functions/circular refs
 */
function isDeepEqual<T>(a: T, b: T): boolean {
  // Fast path: Same reference
  if (a === b) return true;

  // Fast path: Primitives
  if (typeof a !== 'object' || typeof b !== 'object') {
    return a === b;
  }

  // Null check
  if (a === null || b === null) {
    return a === b;
  }

  // JSON serialization (sufficient for form values)
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch (error) {
    // Fallback to reference equality if serialization fails
    console.warn('[useDebounceDeep] Deep equality check failed, using reference equality', error);
    return a === b;
  }
}

// ============================================================================
// HOOK
// ============================================================================

export function useDebounceDeep<T>(value: T, delay: number = 250): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);
  const previousValueRef = useRef<T>(value);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Check if value actually changed (deep comparison)
    const valueChanged = !isDeepEqual(previousValueRef.current, value);

    if (!valueChanged) {
      // Value didn't change → no need to reset timer or update
      return;
    }

    // Value changed → update ref and set debounce timer
    previousValueRef.current = value;

    // Clear existing timer
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }

    // Set new timer
    timerRef.current = setTimeout(() => {
      setDebouncedValue(value);
      timerRef.current = null;
    }, delay);

    // Cleanup: Clear timer on unmount or value change
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [value, delay]);

  return debouncedValue;
}

// ============================================================================
// VARIANT: useDebouncePrimitive (Lightweight)
// ============================================================================

/**
 * Debounce hook for primitive values (no deep equality check)
 *
 * Use this for numbers, strings, booleans where reference equality is sufficient.
 * Faster than useDebounceDeep for primitives.
 *
 * @template T - Primitive type (string, number, boolean)
 */
export function useDebouncePrimitive<T extends string | number | boolean>(
  value: T,
  delay: number = 250
): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Clear existing timer
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }

    // Set new timer
    timerRef.current = setTimeout(() => {
      setDebouncedValue(value);
      timerRef.current = null;
    }, delay);

    // Cleanup
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [value, delay]);

  return debouncedValue;
}

// ============================================================================
// VARIANT: useDebounceCallback (For Functions)
// ============================================================================

/**
 * Debounce a callback function
 *
 * **Example:**
 * ```typescript
 * const debouncedSave = useDebounceCallback((data) => {
 *   onSave(data);
 * }, 500);
 *
 * // Call immediately, but execution delayed
 * debouncedSave(formValues);
 * ```
 */
export function useDebounceCallback<Args extends any[]>(
  callback: (...args: Args) => void,
  delay: number = 250
) {
  const callbackRef = useRef(callback);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Update callback ref (avoid stale closures)
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  // Create debounced function
  const debouncedCallback = useRef((...args: Args) => {
    // Clear existing timer
    if (timerRef.current) {
      clearTimeout(timerRef.current);
    }

    // Set new timer
    timerRef.current = setTimeout(() => {
      callbackRef.current(...args);
      timerRef.current = null;
    }, delay);
  });

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, []);

  return debouncedCallback.current;
}

import { useState, useEffect, useCallback, useRef } from 'react';
import type { Socket } from 'socket.io-client';
import { io } from 'socket.io-client';

interface DevHealthMetrics {
  typescript: {
    errorCount: number;
    errors: Array<{ file: string; line: number; message: string }>;
    trend: 'improving' | 'stable' | 'degrading';
  };
  tests: {
    status: 'passing' | 'failing' | 'unknown';
    passCount: number;
    failCount: number;
    coverage: number;
    performance: {
      avgDuration: number;
      slowTests: Array<{ name: string; duration: number }>;
    };
  };
  build: {
    status: 'success' | 'failed' | 'building';
    duration: number;
    size: {
      client: number;
      server: number;
    };
    warnings: number;
  };
  monteCarlo: {
    status: 'healthy' | 'degraded' | 'offline';
    avgLatency: number;
    throughput: number;
    errorRate: number;
  };
  database: {
    status: 'connected' | 'disconnected' | 'degraded';
    latency: number;
    connectionCount: number;
  };
  devServer: {
    status: 'running' | 'stopped' | 'error';
    port: number;
    memory: number;
    uptime: number;
  };
  git: {
    branch: string;
    uncommittedChanges: number;
    lastCommit: {
      hash: string;
      message: string;
      timestamp: string;
    };
  };
}

interface DashboardData {
  timestamp: string;
  overall: 'healthy' | 'warning' | 'critical';
  metrics: DevHealthMetrics;
}

interface DevDashboardEvent {
  type: 'metrics_update' | 'build_started' | 'build_completed' | 'build_failed' | 'test_started' | 'test_completed' | 'test_failed';
  data: any;
}

interface QuickFixAction {
  id: string;
  label: string;
  icon: string;
  description: string;
  action: () => Promise<void>;
  isRunning: boolean;
}

export const useDevDashboard = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [isConnected, setIsConnected] = useState(false);
  const [realtimeEvents, setRealtimeEvents] = useState<DevDashboardEvent[]>([]);
  const [runningActions, setRunningActions] = useState<Set<string>>(new Set());

  const socketRef = useRef<Socket | null>(null);

  // Fetch initial data from REST API
  const fetchHealth = useCallback(async () => {
    try {
      const response = await fetch('/api/dev-dashboard/health');
      if (!response.ok) throw new Error('Failed to fetch health data');
      const newData = await response.json();
      setData(newData);
      setError(null);
      setLastUpdated(new Date());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  }, []);

  // Quick fix actions
  const createQuickFixAction = useCallback((
    id: string,
    label: string,
    icon: string,
    description: string,
    endpoint: string
  ): QuickFixAction => ({
    id,
    label,
    icon,
    description,
    isRunning: runningActions.has(id),
    action: async () => {
      setRunningActions(prev => new Set(prev).add(id));
      setError(null);

      try {
        const response = await fetch(`/api/dev-dashboard/fix/${endpoint}`, {
          method: 'POST'
        });
        const result = await response.json();

        if (result.success) {
          // Refresh data after successful fix
          await fetchHealth();

          // Add success event to realtime feed
          setRealtimeEvents(prev => [
            {
              type: 'build_completed',
              data: {
                timestamp: new Date().toISOString(),
                message: result.message
              }
            },
            ...prev.slice(0, 9) // Keep last 10 events
          ]);
        } else {
          setError(result.message);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Fix failed');
      } finally {
        setRunningActions(prev => {
          const newSet = new Set(prev);
          newSet.delete(id);
          return newSet;
        });
      }
    }
  }), [runningActions, fetchHealth]);

  const quickFixActions: QuickFixAction[] = [
    createQuickFixAction(
      'typescript',
      'Fix TypeScript',
      'wrench',
      'Run type checking and auto-fix linting issues',
      'typescript'
    ),
    createQuickFixAction(
      'tests',
      'Run Tests',
      'test-tube',
      'Execute the test suite and show results',
      'tests'
    ),
    createQuickFixAction(
      'build',
      'Rebuild',
      'zap',
      'Trigger a fast development build',
      'build'
    )
  ];

  // Trigger build via WebSocket
  const triggerBuild = useCallback(() => {
    if (socketRef.current) {
      socketRef.current.emit('trigger_build');
    }
  }, []);

  // Trigger tests via WebSocket
  const triggerTests = useCallback(() => {
    if (socketRef.current) {
      socketRef.current.emit('trigger_tests');
    }
  }, []);

  // Request immediate metrics update
  const requestMetricsUpdate = useCallback(() => {
    if (socketRef.current) {
      socketRef.current.emit('request_metrics');
    } else {
      fetchHealth();
    }
  }, [fetchHealth]);

  // Setup WebSocket connection for real-time updates
  useEffect(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}`;

    socketRef.current = io(wsUrl, {
      path: '/socket.io/dev-dashboard',
      transports: ['websocket', 'polling']
    });

    socketRef.current.on('connect', () => {
      setIsConnected(true);
      console.log('Connected to dev dashboard WebSocket');
    });

    socketRef.current.on('disconnect', () => {
      setIsConnected(false);
      console.log('Disconnected from dev dashboard WebSocket');
    });

    socketRef.current.on('dev_dashboard_event', (event: DevDashboardEvent) => {
      console.log('Received dev dashboard event:', event);

      // Add event to realtime feed
      setRealtimeEvents(prev => [event, ...prev.slice(0, 9)]);

      // Update metrics if it's a metrics update
      if (event.type === 'metrics_update') {
        setData({
          timestamp: event.data.timestamp,
          overall: event.data.overall,
          metrics: event.data.metrics
        });
        setLastUpdated(new Date());
      }

      // Handle build events
      if (event.type === 'build_started') {
        setData(prev => prev ? {
          ...prev,
          metrics: {
            ...prev.metrics,
            build: {
              ...prev.metrics.build,
              status: 'building'
            }
          }
        } : null);
      }

      if (event.type === 'build_completed') {
        // Refresh full metrics after build completion
        setTimeout(fetchHealth, 1000);
      }
    });

    // Initial fetch
    fetchHealth();

    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
      }
    };
  }, [fetchHealth]);

  // Periodic fallback refresh (in case WebSocket fails)
  useEffect(() => {
    const interval = setInterval(() => {
      if (!isConnected) {
        fetchHealth();
      }
    }, 30000); // 30 seconds

    return () => clearInterval(interval);
  }, [isConnected, fetchHealth]);

  return {
    data,
    loading,
    error,
    lastUpdated,
    isConnected,
    realtimeEvents,
    quickFixActions,
    triggerBuild,
    triggerTests,
    requestMetricsUpdate,
    refresh: fetchHealth
  };
};

import { useState, useEffect } from 'react';
import React from 'react';
import featureConfig from '../config/features.json';

type FeatureFlagName = keyof typeof featureConfig;

/**
 * Hook to check if a feature flag is enabled
 * @param flagName - The name of the feature flag
 * @param defaultValue - Default value if flag is not found
 * @returns boolean indicating if the feature is enabled
 */
export function useFeatureFlag(flagName: FeatureFlagName, defaultValue = false): boolean {
  const [isEnabled, setIsEnabled] = useState(defaultValue);

  useEffect(() => {
    // Check environment variable override first
    const envOverride = import.meta.env[`VITE_FEATURE_${flagName.toUpperCase().replace(/-/g, '_')}`];
    if (envOverride !== undefined) {
      setIsEnabled(envOverride === 'true');
      return;
    }

    // Check config file
    const flagConfig = featureConfig[flagName];
    if (flagConfig) {
      setIsEnabled(flagConfig.enabled);
    } else {
      setIsEnabled(defaultValue);
    }
  }, [flagName, defaultValue]);

  return isEnabled;
}

/**
 * Get all feature flags and their status
 * @returns Object with all feature flags and their enabled status
 */
export function useAllFeatureFlags(): Record<FeatureFlagName, boolean> {
  const [flags, setFlags] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const allFlags: Record<string, boolean> = {};

    Object.keys(featureConfig).forEach((key: any) => {
      const flagName = key as FeatureFlagName;
      const envOverride = import.meta.env[`VITE_FEATURE_${flagName.toUpperCase().replace(/-/g, '_')}`];

      if (envOverride !== undefined) {
        allFlags[flagName] = envOverride === 'true';
      } else {
        allFlags[flagName] = featureConfig[flagName].enabled;
      }
    });

    setFlags(allFlags);
  }, []);

  return flags as Record<FeatureFlagName, boolean>;
}

/**
 * Component wrapper that only renders children if feature flag is enabled
 */
export function FeatureFlag({ 
  flag, 
  children, 
  fallback = null 
}: { 
  flag: FeatureFlagName;
  children: React.ReactNode;
  fallback?: React.ReactNode;
}) {
  const isEnabled = useFeatureFlag(flag);

  if (isEnabled) {
    return React.createElement(React.Fragment, null, children);
  }

  return React.createElement(React.Fragment, null, fallback);
}

/**
 * Feature Flag Hook for React
 * Client-side flag consumption with SWR caching
 */

import { useQuery } from '@tanstack/react-query';

interface FlagResponse {
  flags: Record<string, boolean>;
  timestamp: string;
  _meta: {
    note: string;
  };
}

interface FlagStatus {
  cache: {
    age: number;
    hash: string;
    flagCount: number;
  };
  killSwitchActive: boolean;
  environment: string;
  timestamp: string;
}

/**
 * Fetch client-safe flags from API
 */
async function fetchFlags(): Promise<FlagResponse> {
  const response = await fetch('/api/flags');

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  }

  return response.json();
}

/**
 * Fetch flag system status
 */
async function fetchFlagStatus(): Promise<FlagStatus> {
  const response = await fetch('/api/flags/status');

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  }

  return response.json();
}

/**
 * Hook to get all client-safe flags
 */
export function useFlags() {
  return useQuery({
    queryKey: ['flags'],
    queryFn: fetchFlags,
    staleTime: 25_000, // 25s (slightly less than server TTL of 30s)
    refetchInterval: 30_000, // Refetch every 30s
    refetchOnWindowFocus: true,
    retry: (failureCount: any, error: any) => {
      // Don't retry on 4xx errors, do retry on network/5xx errors
      if (error && typeof error === 'object' && 'message' in error) {
        const message = (error as Error).message;
        if (message.includes('HTTP 4')) return false;
      }
      return failureCount < 3;
    },
    // Safe fallback on error
    placeholderData: { flags: {}, timestamp: new Date().toISOString(), _meta: { note: 'Fallback - all flags disabled' } }
  });
}

/**
 * Hook to check if a specific flag is enabled
 */
export function useFlag(key: string): boolean {
  const { data } = useFlags();
  return data?.flags[key] ?? false;
}

/**
 * Hook to get flag system status (for debugging/monitoring)
 */
export function useFlagStatus() {
  return useQuery({
    queryKey: ['flags', 'status'],
    queryFn: fetchFlagStatus,
    staleTime: 60_000, // 1 minute
    refetchInterval: 120_000, // Every 2 minutes
    retry: 2
  });
}

/**
 * Component for flag debugging (development only)
 */
export function FlagDebugPanel() {
  const { data: flags, isLoading: flagsLoading } = useFlags();
  const { data: status, isLoading: statusLoading } = useFlagStatus();

  if (process.env['NODE_ENV'] !== 'development') {
    return null;
  }

  if (flagsLoading || statusLoading) {
    return <div className="text-sm text-gray-500">Loading flags...</div>;
  }

  return (
    <div className="fixed bottom-4 right-4 bg-black/80 text-white text-xs p-3 rounded max-w-sm">
      <div className="font-bold mb-2">🚩 Feature Flags</div>

      <div className="space-y-1">
        {Object.entries(flags?.flags || {}).map(([key, enabled]) => (
          <div key={key} className="flex justify-between">
            <span className="text-gray-300">{key}:</span>
            <span className={enabled ? 'text-green-400' : 'text-red-400'}>
              {enabled ? 'ON' : 'OFF'}
            </span>
          </div>
        ))}
      </div>

      {status && (
        <div className="mt-3 pt-2 border-t border-gray-600">
          <div className="text-gray-400">
            Cache: {Math.round(status.cache.age / 1000)}s ago ({status.cache.hash})
          </div>
          {status.killSwitchActive && (
            <div className="text-red-400 font-bold">🚨 KILL SWITCH ACTIVE</div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * TanStack Query Integration for Fund KPIs
 *
 * Custom hook that integrates fund KPI selectors with TanStack Query for:
 * - Automatic refetching and caching
 * - Loading and error states
 * - Optimistic updates
 * - Derived state with selectors
 *
 * @module useFundKpis
 */

import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';
import type { FundData, FundKPIs } from '@/core/types/fund-domain';
import {
  selectCommitted,
  selectCalled,
  selectUncalled,
  selectInvested,
  selectDistributions,
  selectNAV,
  selectDPI,
  selectTVPI,
  selectIRR,
  selectAllKPIs,
} from '@/core/selectors/fund-kpis';

/**
 * Options for useFundKpis hook
 */
interface UseFundKpisOptions {
  fundId: number;
  asOf?: string | undefined; // Optional "as of" date for historical snapshots
  enabled?: boolean | undefined; // Whether to enable the query
  refetchInterval?: number | undefined; // Auto-refetch interval in milliseconds
}

/**
 * Individual KPI selector hook
 * Use this when you only need a single KPI to minimize re-renders
 */
interface UseKpiSelectorOptions<T> {
  fundId: number;
  asOf?: string | undefined;
  enabled?: boolean | undefined;
  selector: (data: FundData, asOf?: string) => T;
}

/**
 * Fetch fund data for KPI calculations
 * This would typically call your API endpoint
 *
 * @param fundId - Fund ID to fetch
 * @returns Promise resolving to FundData
 */
async function fetchFundData(fundId: number): Promise<FundData> {
  const response = await fetch(`/api/funds/${fundId}/data`);

  if (!response.ok) {
    throw new Error(`Failed to fetch fund data: ${response.statusText}`);
  }

  return response.json();
}

/**
 * Main hook for accessing all fund KPIs
 *
 * Uses TanStack Query to fetch fund data and calculate KPIs.
 * KPIs are memoized to prevent unnecessary recalculations.
 *
 * @param options - Hook configuration options
 * @returns Query result with KPIs and metadata
 *
 * @example
 * ```typescript
 * function FundDashboard({ fundId }: { fundId: number }) {
 *   const { data: kpis, isLoading, error } = useFundKpis({ fundId });
 *
 *   if (isLoading) return <Spinner />;
 *   if (error) return <Error message={error.message} />;
 *
 *   return (
 *     <div>
 *       <Metric label="TVPI" value={`${kpis.tvpi.toFixed(2)}x`} />
 *       <Metric label="DPI" value={`${kpis.dpi.toFixed(2)}x`} />
 *       <Metric label="IRR" value={`${(kpis.irr * 100).toFixed(1)}%`} />
 *     </div>
 *   );
 * }
 * ```
 */
export function useFundKpis(options: UseFundKpisOptions) {
  const { fundId, asOf, enabled = true, refetchInterval } = options;

  // Fetch fund data using TanStack Query
  const query = useQuery({
    queryKey: ['fundData', fundId] as const,
    queryFn: () => fetchFundData(fundId),
    enabled,
    staleTime: 5 * 60 * 1000, // 5 minutes
    gcTime: 10 * 60 * 1000, // 10 minutes (formerly cacheTime)
    ...(refetchInterval !== undefined ? { refetchInterval } : {}),
    refetchOnWindowFocus: true,
  });

  // Calculate KPIs using memoized selector
  // This prevents recalculation on every render
  const kpis = useMemo(() => {
    if (!query.data) return null;
    return selectAllKPIs(query.data, asOf ?? undefined);
  }, [query.data, asOf]);

  return {
    ...query,
    data: kpis,
  };
}

/**
 * Hook for selecting a specific KPI
 *
 * More performant than useFundKpis when you only need one KPI value,
 * as it minimizes re-renders and recalculations.
 *
 * @param options - Selector options
 * @returns Query result with selected KPI value
 *
 * @example
 * ```typescript
 * function TVPIDisplay({ fundId }: { fundId: number }) {
 *   const { data: tvpi, isLoading } = useKpiSelector({
 *     fundId,
 *     selector: selectTVPI,
 *   });
 *
 *   if (isLoading) return <Skeleton />;
 *   return <div>TVPI: {tvpi?.toFixed(2)}x</div>;
 * }
 * ```
 */
export function useKpiSelector<T>(options: UseKpiSelectorOptions<T>) {
  const { fundId, asOf, enabled = true, selector } = options;

  const query = useQuery({
    queryKey: ['fundData', fundId] as const,
    queryFn: () => fetchFundData(fundId),
    enabled,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    refetchOnWindowFocus: true,
  });

  const selectedValue = useMemo(() => {
    if (!query.data) return null;
    return selector(query.data, asOf ?? undefined);
  }, [query.data, asOf, selector]);

  return {
    ...query,
    data: selectedValue,
  };
}

