 *
 *   return (
 *     <LineChart data={snapshots.map(s => ({ date: s.asOf, tvpi: s.tvpi }))} />
 *   );
 * }
 * ```
 */
export function useKpiHistory(options: {
  fundId: number;
  dates: string[];
  enabled?: boolean;
}) {
  const { fundId, dates, enabled = true } = options;

  const query = useQuery({
