import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import { api } from '@/lib';

// Local state for UI toggle
interface ToggleStore {
  mode: 'construction' | 'current';
  isTransitioning: boolean;
  setMode: (mode: 'construction' | 'current') => void;
  setTransitioning: (transitioning: boolean) => void;
}

const useToggleStore = create<ToggleStore>()(subscribeWithSelector(
  (set, get): ToggleStore => ({
    mode: 'current' as const,
    isTransitioning: false,
    setMode: (mode: 'construction' | 'current') => set({ mode }),
    setTransitioning: (transitioning: boolean) => set({ isTransitioning: transitioning }),
  })
));

// API response with pre-computed delta
interface FundStateResponse {
  fundId: number;
  mode: 'construction' | 'current';
  state: any;
  delta?: {
    capitalLeft: number;
    irr: number;
    tvpi: number;
    companiesCount: number;
  };
  patch?: any[]; // Immer patches for efficient updates
  checksum: string;
}

export function useFundToggle(fundId: number) {
  const queryClient = useQueryClient();
  const { mode, isTransitioning, setMode, setTransitioning } = useToggleStore();

  // Fetch both states with React Query caching
  const constructionQuery = useQuery({
    queryKey: ['fund', fundId, 'construction'],
    queryFn: () => api.get<FundStateResponse>(`/funds/${fundId}/state/construction`),
    staleTime: 5 * 60 * 1000, // 5 minutes
    gcTime: 10 * 60 * 1000, // 10 minutes
  });

  const currentQuery = useQuery({
    queryKey: ['fund', fundId, 'current'],
    queryFn: () => api.get<FundStateResponse>(`/funds/${fundId}/state/current`),
    staleTime: 1 * 60 * 1000, // 1 minute (more frequent updates)
    gcTime: 5 * 60 * 1000, // 5 minutes
  });

  // Toggle mutation with optimistic updates
  const toggleMutation = useMutation({
    mutationFn: async (newMode: 'construction' | 'current') => {
      // API returns the delta for UI to render immediately
      return api.post<FundStateResponse>(`/funds/${fundId}/toggle`, { mode: newMode });
    },
    onMutate: async (newMode: 'construction' | 'current') => {
      setTransitioning(true);
      setMode(newMode);

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: ['fund', fundId] });

      // Return context for rollback
      return { previousMode: mode };
    },
    onError: (err: any, newMode: 'construction' | 'current', context: any) => {
      // Rollback on error
      if (context?.previousMode) {
        setMode(context.previousMode);
      }
      setTransitioning(false);
    },
    onSuccess: (data: any) => {
      // Update cache with new data
      queryClient.setQueryData(['fund', fundId, data.mode], data);
      setTransitioning(false);
    },
    onSettled: () => {
      // Refetch to ensure consistency
      queryClient.invalidateQueries({ queryKey: ['fund', fundId] });
    },
  });

  // Get active state based on mode
  const activeQuery = mode === 'construction' ? constructionQuery : currentQuery;
  const activeState = activeQuery.data;

  // Pre-compute UI values
  const uiState = activeState ? {
    fundId,
    mode,
    isLoading: activeQuery.isLoading || isTransitioning,
    isError: activeQuery.isError,
    error: activeQuery.error,

    // Direct values from pre-computed delta
    capitalLeft: activeState.delta?.capitalLeft || 0,
    irr: activeState.delta?.irr || 0,
    tvpi: activeState.delta?.tvpi || 0,
    companiesCount: activeState.delta?.companiesCount || 0,

    // Full state for detailed views
    state: activeState.state,
    checksum: activeState.checksum,
  } : null;

  return {
    ...uiState,
    toggle: (newMode: 'construction' | 'current') => {
      if (newMode !== mode && !isTransitioning) {
        toggleMutation.mutate(newMode);
      }
    },
    prefetch: () => {
      // Prefetch both states for instant switching
      queryClient.prefetchQuery({
        queryKey: ['fund', fundId, 'construction'],
        queryFn: () => api.get<FundStateResponse>(`/funds/${fundId}/state/construction`),
      });
      queryClient.prefetchQuery({
        queryKey: ['fund', fundId, 'current'],
        queryFn: () => api.get<FundStateResponse>(`/funds/${fundId}/state/current`),
      });
    },
  };
}

// Subscribe to mode changes for analytics
useToggleStore.subscribe(
  (state: ToggleStore) => state.mode,
  (mode: 'construction' | 'current') => {
    // Track mode changes
    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('event', 'fund_mode_toggle', {
        mode,
        timestamp: new Date().toISOString(),
      });
    }
  }
);

/**
 * useLPCapitalAccount Hook
 *
 * Data fetching hook for LP capital account transactions with pagination.
 *
 * @module client/hooks/useLPCapitalAccount
 */

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useLPContext } from '@/contexts/LPContext';
import type {
  CapitalAccountResponse,
  CapitalAccountQuery,
} from '@shared/types/lp-api';

// ============================================================================
// HOOK
// ============================================================================

interface UseLPCapitalAccountOptions extends Omit<CapitalAccountQuery, 'cursor'> {
  enabled?: boolean;
}

/**
 * Hook for fetching LP capital account transactions
 *
 * Supports filtering, sorting, and cursor-based pagination.
 *
 * @example
 * ```tsx
 * const { data, isLoading, fetchNextPage } = useLPCapitalAccount({
 *   fundId: 1,
 *   startDate: '2024-01-01',
 *   types: ['capital_call', 'distribution'],
 *   limit: 20,
 * });
 * ```
 */
export function useLPCapitalAccount(options: UseLPCapitalAccountOptions = {}) {
  const { lpId } = useLPContext();
  const {
    fundId,
    startDate,
    endDate,
    types,
    limit = 50,
    sortBy = 'transactionDate',
    sortOrder = 'desc',
    enabled = true,
  } = options;

  const queryClient = useQueryClient();

  const query = useQuery<CapitalAccountResponse, Error>({
    queryKey: ['lp-capital-account', lpId, fundId, startDate, endDate, types, sortBy, sortOrder, limit],
    queryFn: async () => {
      if (!lpId) {
        throw new Error('No LP ID available');
      }

      const params = new URLSearchParams();
      if (fundId) params.append('fundId', fundId.toString());
      if (startDate) params.append('startDate', startDate);
      if (endDate) params.append('endDate', endDate);
      if (types && types.length > 0) params.append('types', types.join(','));
      params.append('limit', limit.toString());
      params.append('sortBy', sortBy);
      params.append('sortOrder', sortOrder);

      const response = await fetch(
        `/api/lp/capital-account?lpId=${lpId}&${params.toString()}`
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || `HTTP ${response.status}: Failed to fetch capital account`);
      }

      return response.json();
    },
    enabled: enabled && !!lpId,
    staleTime: 60_000, // 1 minute
    gcTime: 300_000, // 5 minutes
    refetchOnWindowFocus: false,
    retry: 2,
  });

  // Helper to fetch next page
  const fetchNextPage = async () => {
    if (query.data?.pagination.hasMore && query.data?.pagination.cursor) {
      const nextCursor = query.data.pagination.cursor;
      await queryClient.fetchQuery({
        queryKey: ['lp-capital-account', lpId, fundId, startDate, endDate, types, sortBy, sortOrder, limit, nextCursor],
        queryFn: async () => {
          if (!lpId) {
            throw new Error('No LP ID available');
          }

          const params = new URLSearchParams();
          if (fundId) params.append('fundId', fundId.toString());
          if (startDate) params.append('startDate', startDate);
          if (endDate) params.append('endDate', endDate);
          if (types && types.length > 0) params.append('types', types.join(','));
          params.append('cursor', nextCursor);
          params.append('limit', limit.toString());
          params.append('sortBy', sortBy);
          params.append('sortOrder', sortOrder);

          const response = await fetch(
            `/api/lp/capital-account?lpId=${lpId}&${params.toString()}`
          );

          if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `HTTP ${response.status}: Failed to fetch next page`);
          }

          return response.json();
        },
      });
    }
  };

  return {
    ...query,
    fetchNextPage,
    hasNextPage: query.data?.pagination.hasMore || false,
  };
}

/**
 * Hook for invalidating LP capital account cache
 */
export function useInvalidateLPCapitalAccount() {
  const { lpId } = useLPContext();
  const queryClient = useQueryClient();

  const invalidate = async () => {
    if (!lpId) return;

    await queryClient.invalidateQueries({
      predicate: (query) => {
        const key = query.queryKey[0] as string;
        return key === 'lp-capital-account' && query.queryKey[1] === lpId;
      },
    });
  };

  return { invalidate };
}

