  eventCount: number;
  stateHash: string;
  metadata: any;
}

export interface TimelineData {
  fundId: number;
  timeRange: {
    start: string;
    end: string;
  };
  events: TimelineEvent[];
  snapshots: Snapshot[];
  pagination: {
    total: number;
    limit: number;
    offset: number;
    hasMore: boolean;
  };
