/**
 * Wizard Calculations Hook
 *
 * Provides reactive validation, summary, and enriched metrics for the modeling wizard.
 * Optimized with specific useMemo dependencies to prevent unnecessary recalculations.
 */

import { useMemo } from 'react';
import {
  validateWizardPortfolio,
  enrichWizardMetrics,
  generatePortfolioSummary,
  type WizardPortfolioCompany,
  type PortfolioValidationResult,
  type PortfolioSummary,
  type EnrichedReserveAllocation
} from '@/lib/wizard-calculations';
import type { ModelingWizardContext } from '@/machines/modeling-wizard.machine';

/**
 * Hook for wizard calculation operations
 * Provides validation, summary, and reserve calculation helpers
 *
 * @param portfolio - Array of portfolio companies
 * @param wizardContext - Strongly-typed wizard machine context (NO ANY!)
 */
export function useWizardCalculations(
  portfolio: WizardPortfolioCompany[],
  wizardContext: ModelingWizardContext | undefined
) {
  // Portfolio validation (recalculates when portfolio changes)
  const validation: PortfolioValidationResult = useMemo(
    () => validateWizardPortfolio(portfolio),
    [portfolio]
  );

  // Portfolio summary (recalculates when portfolio changes)
  const summary: PortfolioSummary = useMemo(
    () => generatePortfolioSummary(portfolio),
    [portfolio]
  );

  // Get enriched metrics if reserves are calculated
  // Keep deps narrow but include the context reference to avoid stale closures.
  const reserveAllocation = wizardContext?.calculations?.reserves;
  const generalInfo = wizardContext?.steps?.generalInfo;
  const capitalAllocation = wizardContext?.steps?.capitalAllocation;

  const enrichedMetrics: EnrichedReserveAllocation | null = useMemo(() => {
    if (!reserveAllocation || !wizardContext) return null;

    return enrichWizardMetrics(reserveAllocation, wizardContext);
  }, [
    reserveAllocation,
    generalInfo,
    capitalAllocation,
    wizardContext
  ]);

  // Check if portfolio is ready for calculation
  const isReadyForCalculation = useMemo(() => {
    return (
      validation.valid &&
      portfolio.length > 0 &&
      generalInfo != null &&
      capitalAllocation != null
    );
  }, [
    validation.valid,
    portfolio.length,
    generalInfo,
    capitalAllocation
  ]);

  return {
    // Validation
    validation,
    isValid: validation.valid,
    hasErrors: validation.errors.length > 0,
    hasWarnings: validation.warnings.length > 0,

    // Summary
    summary,

    // Enriched metrics (if calculated)
    enrichedMetrics,

    // Calculation readiness
    isReadyForCalculation,

    // Reserve results (if available)
    reserveAllocation,
    hasReserves: !!reserveAllocation
  };
}

import { useEffect, useRef, useState, useCallback } from 'react';

type WorkerType = 'xirr' | 'monte-carlo' | 'waterfall' | 'cancel';
type Resolver = (result: any) => void;

export function useWorkerAnalytics() {
  const workerRef = useRef<Worker | null>(null);
  const pending = useRef<Map<string, Resolver>>(new Map());
  const [progress, setProgress] = useState<Record<string, number>>({});

  useEffect(() => {
    const worker = new Worker(new URL('../workers/analytics.worker.ts', import.meta.url), { type: 'module' });
    workerRef.current = worker;
    worker.onmessage = (e: MessageEvent<any>) => {
      const { id, result, error, progress: p } = e.data ?? {};
      if (p !== undefined) {
        setProgress(prev => ({ ...prev, [id]: p }));
        return;
      }
      const r = pending.current['get'](id);
      if (r) {
        pending.current.delete(id);
        setProgress(prev => {
          const next = { ...prev }; delete next[id]; return next;
        });
        if (error) console.error(`Worker error for ${id}:`, error);
        r(result);
      }
    };
    return () => {
      // Clean up pending promises before terminating worker
      pending.current.forEach((resolve: any, id: any) => {
        resolve(null); // Resolve with null instead of rejecting
      });
      pending.current.clear();
      setProgress({});

      worker.terminate();
      if (workerRef.current === worker) {
        workerRef.current = null;
      }
    };
  }, []);

  const call = useCallback((type: WorkerType, payload: any, id: string) => {
    return new Promise((resolve: any) => {
      if (!workerRef.current) return resolve(null);

      // Set up timeout to prevent hanging promises
      const timeoutId = setTimeout(() => {
        if (pending.current.has(id)) {
          pending.current.delete(id);
          resolve(null);
        }
      }, 30000); // 30 second timeout

      const wrappedResolve = (result: any) => {
        clearTimeout(timeoutId);
        resolve(result);
      };

      pending.current['set'](id, wrappedResolve);
      workerRef.current.postMessage({ id, type, payload });
    });
  }, []);

  const cancel = useCallback((id: string) => {
    if (!workerRef.current) return;
    workerRef.current.postMessage({ id, type: 'cancel' });
    pending.current.delete(id);
    setProgress(prev => { const next = { ...prev }; delete next[id]; return next; });
  }, []);

  // Convenience wrappers
  const calculateXIRR = useCallback((cashFlows: Array<{ date: string; amount: number }>, id: string) =>
    call('xirr', { cashFlows }, id), [call]);

  const runMonteCarlo = useCallback((cashFlows: any[], id: string, volatility = 0.2, runs = 1000) =>
    call('monte-carlo', { cashFlows, volatility, runs, chunkSize: 100 }, id), [call]);

  const calculateWaterfall = useCallback((config: any, contributions: any[], exits: any[], id: string) =>
    call('waterfall', { config, contributions, exits }, id), [call]);

  return { calculateXIRR, runMonteCarlo, calculateWaterfall, cancel, progress };
}

import { useEffect, useRef, useState } from 'react';

type WorkerFactory = () => Worker;

export type WorkerResult<TOut> = {
  data: TOut | null;
  loading: boolean;
  error: Error | null;
  timing?: number | undefined;
};

/**
 * Compute off the main thread. Spawns a fresh worker when deps change,
 * cancels the previous one, and returns {data, loading, error}.
 */
export function useWorkerMemo<TIn, TOut>(
  makeWorker: WorkerFactory,
  input: TIn | null,
): WorkerResult<TOut> {
  const [data, setData] = useState<TOut | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [timing, setTiming] = useState<number | undefined>(undefined);
  const workerRef = useRef<Worker | null>(null);

  useEffect(() => {
    if (input == null) {
      setData(null);
      setLoading(false);
      setError(null);
      setTiming(undefined);
      return;
    }

    setLoading(true);
    setError(null);
    setTiming(undefined);

    // Kill previous worker
    if (workerRef.current) {
      workerRef.current.terminate();
    }

    const w = makeWorker();
    workerRef.current = w;

    w.onmessage = (e: MessageEvent<{ ok: boolean; result?: TOut; error?: string; timing?: number }>) => {
      if (!w || w !== workerRef.current) return; // stale

      if (e.data.ok) {
        setData(e.data.result ?? null);
        setLoading(false);
        if (e.data.timing && import.meta.env.DEV) {
          setTiming(e.data.timing);
          console.log(`[WORKER] Computation took ${e.data.timing.toFixed(2)}ms`);
        }
      } else {
        setError(new Error(e.data.error || 'Worker error'));
        setLoading(false);
      }
    };

    w.onerror = (ev: any) => {
      if (!w || w !== workerRef.current) return;
      setError(ev instanceof ErrorEvent ? ev.error : new Error('Worker error'));
      setLoading(false);
    };

    // Send input to worker
    w.postMessage(input);

    return () => {
      w.terminate();
      if (workerRef.current === w) {
        workerRef.current = null;
      }
    };
  }, [makeWorker, input]);

  const result: WorkerResult<TOut> = {
    data,
    loading,
    error,
    ...(timing !== undefined ? { timing } : {}),
  };
  return result;
}

/**
 * CalculationCache: LRU with TTL and stable hashing.
 * - Uses Web Crypto if available, falls back to Node 'crypto' in tests/SSR.
 * - Updates recency on get() via Map deletion+set.
 */
export class CalculationCache<TInput, TData> {
  private cache = new Map<string, { data: TData; ts: number }>();
  constructor(private maxSize = 100, private ttlMs = 5 * 60 * 1000) {}

  private async hashJSON(obj: TInput): Promise<string> {
    const json = JSON.stringify(obj);
    // Browser path
    if (typeof globalThis.crypto !== 'undefined' && (globalThis.crypto as any).subtle) {
      const enc = new TextEncoder().encode(json);
      const digest = await (globalThis.crypto as any).subtle.digest('SHA-256', enc);
      return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
    // Node path (tests/SSR)
    try {
      // @ts-ignore dynamic import for Node only
      const { createHash } = await import('crypto');
      return createHash('sha256').update(json).digest('hex');
    } catch {
      // Last-resort poor-man hash (non-cryptographic)
      let h = 0;
      for (let i = 0; i < json.length; i++) {
        h = ((h << 5) - h) + json.charCodeAt(i);
        h |= 0;
      }
      return String(h >>> 0);
    }
  }

  private touch(k: string) {
    const v = this.cache['get'](k);
    if (!v) return;
    this.cache.delete(k);
    this.cache['set'](k, v); // move to MRU
  }

  async get(input: TInput): Promise<TData | null> {
    const k = await this.hashJSON(input);
    const v = this.cache['get'](k);
    if (!v) return null;
    if (Date.now() - v.ts > this.ttlMs) {
      this.cache.delete(k);
      return null;
    }
    this.touch(k);
    return v.data;
  }

  async set(input: TInput, data: TData): Promise<void> {
    const k = await this.hashJSON(input);
    if (this.cache.size >= this.maxSize) {
      const oldest = this.cache.keys().next().value;
      if (oldest !== undefined) {
        this.cache.delete(oldest);
      }
    }
    this.cache['set'](k, { data, ts: Date.now() });
  }

  // Clear all cached data - useful for tests and manual cache management
  clear(): void {
    this.cache.clear();
  }

  // Get cache statistics
  getStats() {
    return {
      size: this.cache.size,
      maxSize: this.maxSize,
      ttlMs: this.ttlMs
    };
  }
}

