/**
 * Quarter-based time utilities
 * Using integer quarterIndex for deterministic time calculations
 * quarterIndex = year * 4 + (quarter - 1)
 */

export interface QuarterTime {
  year: number;
  quarter: 1 | 2 | 3 | 4;
}

export interface QuarterRange {
  start: QuarterTime;
  end: QuarterTime;
}

// Core conversion functions
export function toQuarterIndex(qt: QuarterTime): number {
  return qt.year * 4 + (qt.quarter - 1);
}

export function fromQuarterIndex(index: number): QuarterTime {
  const year = Math.floor(index / 4);
  const quarter = ((index % 4) + 1) as 1 | 2 | 3 | 4;
  return { year, quarter };
}

// Date conversions
export function dateToQuarter(date: Date): QuarterTime {
  const year = date.getFullYear();
  const month = date.getMonth(); // 0-based
  const quarter = (Math.floor(month / 3) + 1) as 1 | 2 | 3 | 4;
  return { year, quarter };
}

export function quarterToDate(qt: QuarterTime, endOfQuarter: boolean = false): Date {
  const month = (qt.quarter - 1) * 3;
  if (endOfQuarter) {
    // Last day of the quarter
    const lastMonth = month + 2;
    const lastDay = [31, 30, 30, 31][qt.quarter - 1]; // Mar, Jun, Sep, Dec
    return new Date(qt.year, lastMonth, lastDay, 23, 59, 59, 999);
  } else {
    // First day of the quarter
    return new Date(qt.year, month, 1, 0, 0, 0, 0);
  }
}

// Quarter arithmetic
export function addQuarters(qt: QuarterTime, quarters: number): QuarterTime {
  const index = toQuarterIndex(qt);
  return fromQuarterIndex(index + quarters);
}

export function quarterDiff(a: QuarterTime, b: QuarterTime): number {
  return toQuarterIndex(a) - toQuarterIndex(b);
}

// Formatting
export function formatQuarter(qt: QuarterTime): string {
  return `Q${qt.quarter} ${qt.year}`;
}

export function parseQuarter(str: string): QuarterTime | null {
  const match = str.match(/Q([1-4])\s+(\d{4})/);
  if (!match) return null;

  return {
    quarter: parseInt(match[1]!) as 1 | 2 | 3 | 4,
    year: parseInt(match[2]!)
  };
}

// Range operations
export function isInQuarterRange(qt: QuarterTime, range: QuarterRange): boolean {
  const index = toQuarterIndex(qt);
  const startIndex = toQuarterIndex(range.start);
  const endIndex = toQuarterIndex(range.end);
  return index >= startIndex && index <= endIndex;
}

export function getQuartersInRange(range: QuarterRange): QuarterTime[] {
  const startIndex = toQuarterIndex(range.start);
  const endIndex = toQuarterIndex(range.end);
  const quarters: QuarterTime[] = [];

  for (let i = startIndex; i <= endIndex; i++) {
    quarters.push(fromQuarterIndex(i));
  }

  return quarters;
}

// Validation
export function isValidQuarter(qt: any): qt is QuarterTime {
  return (
    typeof qt === 'object' &&
    qt !== null &&
    typeof qt.year === 'number' &&
    qt.year >= 1900 &&
    qt.year <= 2100 &&
    typeof qt.quarter === 'number' &&
    qt.quarter >= 1 &&
    qt.quarter <= 4
  );
}

// Current quarter helper
export function getCurrentQuarter(): QuarterTime {
  return dateToQuarter(new Date());
}

export function getCurrentQuarterIndex(): number {
  return toQuarterIndex(getCurrentQuarter());
}

// Excel serial date conversion (for compatibility)
export function quarterToExcelSerial(qt: QuarterTime): number {
  const date = quarterToDate(qt, true); // End of quarter
  const baseDate = new Date(1900, 0, 1);
  const diffTime = date.getTime() - baseDate.getTime();
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  return diffDays + 2; // Excel 1900 date system adjustment
}

export function excelSerialToQuarter(serial: number): QuarterTime {
  const baseDate = new Date(1900, 0, 1);
  const date = new Date(baseDate.getTime() + (serial - 2) * 24 * 60 * 60 * 1000);
  return dateToQuarter(date);
}

// Migration helper for existing date-based data
export function migrateToQuarterIndex(dateStr: string): number {
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) {
    throw new Error(`Invalid date string: ${dateStr}`);
  }
  return toQuarterIndex(dateToQuarter(date));
}

// Export convenience constants
export const QUARTERS_PER_YEAR = 4;
export const MIN_QUARTER_INDEX = 1900 * 4; // Q1 1900
export const MAX_QUARTER_INDEX = 2100 * 4 + 3; // Q4 2100

/**
 * Reserves v1.1 Calculation Engine
 * - Configurable reserve percentage
 * - Optional "remain" pass for additional allocation
 * - Integer cents for precision
 * - Exit MOIC-based ranking
 * - Comprehensive audit trail
 */

import type {
  Company,
  ReservesConfig,
  ReservesInput,
  ReservesOutput,
  ReservesResult,
  AllocationDecision
} from '@shared/types/reserves-v11';

// Helper function to calculate cap for a company
function calculateCap(company: Company, config: ReservesConfig): number {
  const { cap_policy } = config;

  switch (cap_policy.kind) {
    case 'fixed_percent': {
      const percent = cap_policy.default_percent || 0.5; // Default 50%
      return Math.floor((company.invested_cents || 0) * percent);
    }

    case 'stage_based': {
      const stage = company.stage || 'unknown';
      const caps = cap_policy.stage_caps || {};
      const percent = caps[stage] || cap_policy.default_percent || 0.5;
      return Math.floor((company.invested_cents || 0) * percent);
    }

    case 'custom': {
      if (cap_policy.custom_fn) {
        return cap_policy.custom_fn(company);
      }
      return Math.floor((company.invested_cents || 0) * 0.5);
    }

    default:
      return Math.floor((company.invested_cents || 0) * 0.5);
  }
}

// Main calculation function with safety and invariants
export function calculateReservesSafe(
  input: ReservesInput,
  config: ReservesConfig
): ReservesResult {
  const startTime = performance.now();
  const warnings: string[] = [];

  try {
    // Input validation
    if (!input.companies || input.companies.length === 0) {
      return {
        ok: true,
        data: {
          allocations: [],
          remaining_cents: 0,
          metadata: {
            total_available_cents: 0,
            total_allocated_cents: 0,
            companies_funded: 0,
            max_iterations: 0,
            conservation_check: true,
            exit_moic_ranking: []
          }
        },
        warnings: ['No companies provided'],
        metrics: {
          duration_ms: performance.now() - startTime,
          company_count: 0,
          policy_type: config.cap_policy.kind
        }
      };
    }

    // Calculate total available reserves
    const totalInitial = input.companies.reduce((sum: any, c: any) => sum + (c.invested_cents || 0), 0);
    const available = Math.floor((totalInitial * config.reserve_bps) / 10_000);
    let remaining = available;

    // Rank companies by Exit MOIC (descending)
    const ranked = [...input.companies].sort((a: any, b: any) => {
      const moicA = a.exit_moic_bps || 0;
      const moicB = b.exit_moic_bps || 0;
      if (moicB !== moicA) return moicB - moicA;
      // Secondary sort by invested amount for stability
      return (b.invested_cents || 0) - (a.invested_cents || 0);
    });

    const exitMoicRanking = ranked.map(c => c.id);
    const allocations: AllocationDecision[] = [];
    const companyAllocations = new Map<string, number>();

    // Single allocation pass
    const performAllocationPass = (iteration: number) => {
      for (const company of ranked) {
        if (remaining <= 0) break;

        const cap = calculateCap(company, config);
        const already = companyAllocations['get'](company.id) || 0;
        const room = Math.max(0, cap - already);

        if (room <= 0) continue;

        const allot = Math.min(remaining, room);

        if (allot > 0) {
          const newTotal = already + allot;
          companyAllocations['set'](company.id, newTotal);

          // Find and update existing allocation or create new
          const existingIndex = allocations.findIndex(a => a.company_id === company.id);

          if (existingIndex >= 0) {
            allocations[existingIndex] = {
              company_id: company.id,
              planned_cents: newTotal,
              reason: `Ranked #${exitMoicRanking.indexOf(company.id) + 1} by Exit MOIC (${(company.exit_moic_bps || 0) / 100}%), iteration ${iteration}`,
              cap_cents: cap,
              iteration
            };
          } else {
            allocations.push({
              company_id: company.id,
              planned_cents: allot,
              reason: `Ranked #${exitMoicRanking.indexOf(company.id) + 1} by Exit MOIC (${(company.exit_moic_bps || 0) / 100}%), iteration ${iteration}`,
              cap_cents: cap,
              iteration
            });
          }

          remaining -= allot;
        }
      }
    };

    // First pass
    performAllocationPass(1);

    // Optional "remain" pass
    if (config.remain_passes === 1 && remaining > 0) {
      performAllocationPass(2);
    }

    // Calculate totals for invariant checking
    const totalAllocated = allocations.reduce((sum: any, a: any) => sum + a.planned_cents, 0);

    // Conservation invariant check
    const conservationCheck = Math.abs((totalAllocated + remaining) - available) <= 1; // Allow 1 cent rounding

    if (!conservationCheck) {
      warnings.push(`Conservation check failed: allocated=${totalAllocated}, remaining=${remaining}, available=${available}`);
      // Normalize to maintain invariant
      remaining = Math.max(0, available - totalAllocated);
    }

    const output: ReservesOutput = {
      allocations,
      remaining_cents: remaining,
      metadata: {
        total_available_cents: available,
        total_allocated_cents: totalAllocated,
        companies_funded: allocations.length,
        max_iterations: config.remain_passes === 1 ? 2 : 1,
        conservation_check: conservationCheck,
        exit_moic_ranking: exitMoicRanking
      }
    };

    return {
      ok: true,
      data: output,
      ...(warnings.length > 0 ? { warnings } : {}),
      metrics: {
        duration_ms: performance.now() - startTime,
        company_count: input.companies.length,
        policy_type: config.cap_policy.kind
      }
    };

  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : 'Unknown error',
      metrics: {
        duration_ms: performance.now() - startTime,
        company_count: input.companies.length,
        policy_type: config.cap_policy.kind
      }
    };
  }
}

// Export a simpler interface for common use cases
export function calculateReserves(
  companies: Company[],
  reservePercent: number,
  enableRemainPass: boolean = false
): ReservesResult {
  const config: ReservesConfig = {
    reserve_bps: Math.round(reservePercent * 10000),
    remain_passes: enableRemainPass ? 1 : 0,
    cap_policy: {
      kind: 'fixed_percent',
      default_percent: 0.5
    },
    audit_level: 'basic'
  };

  const input: ReservesInput = {
    companies,
    fund_size_cents: companies.reduce((sum: any, c: any) => sum + (c.invested_cents || 0), 0),
    quarter_index: new Date().getFullYear() * 4 + Math.floor(new Date().getMonth() / 3)
  };

  return calculateReservesSafe(input, config);
}

/**
 * Resilient API Client with Exponential Backoff and Circuit Breaker
 * Provides reliable communication with the backend API
 */

interface ApiClientConfig {
  baseUrl?: string;
  timeoutMs?: number;
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  circuitBreakerThreshold?: number;
  circuitBreakerResetMs?: number;
}

interface CircuitBreakerState {
  failures: number;
  lastFailureTime: number;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
}

function isRetryableError(error: any): boolean {
  // Network errors
  if (error.name === 'AbortError' || error.name === 'TypeError') return true;

  // HTTP status codes that should be retried
  const status = error.status;
  return status >= 500 || status === 429 || status === 408 || status === 0;
}

function calculateBackoffDelay(attempt: number, baseDelay: number, maxDelay: number): number {
  const exponentialDelay = baseDelay * Math.pow(2, attempt);
  const jitter = Math.random() * 0.1 * exponentialDelay; // 10% jitter
  return Math.min(exponentialDelay + jitter, maxDelay);
}

export class ResilientApiClient {
  private config: Required<ApiClientConfig>;
  private circuitBreaker: CircuitBreakerState = {
    failures: 0,
    lastFailureTime: 0,
    state: 'CLOSED',
  };

  constructor(config: ApiClientConfig = {}) {
    this.config = {
      baseUrl: config.baseUrl || import.meta.env.VITE_API_BASE_URL || '',
      timeoutMs: config.timeoutMs || 15000,
      maxRetries: config.maxRetries || 3,
      baseDelayMs: config.baseDelayMs || 1000,
      maxDelayMs: config.maxDelayMs || 8000,
      circuitBreakerThreshold: config.circuitBreakerThreshold || 5,
      circuitBreakerResetMs: config.circuitBreakerResetMs || 60000, // 1 minute
    };
  }

  /**
   * Make a POST request with retry logic and circuit breaker
   */
  async post<T>(path: string, body: unknown): Promise<T> {
    // Check circuit breaker
    if (this.isCircuitOpen()) {
      throw new Error('Circuit breaker is OPEN - service unavailable');
    }

    let lastError: Error;

    for (let attempt = 0; attempt < this.config.maxRetries; attempt++) {
      try {
        const response = await this.makeRequest<T>(path, body);
        this.onSuccess();
        return response;
      } catch (error) {
        lastError = error as Error;
        this.onFailure();

        // Don't retry if circuit is now open or error is not retryable
        if (this.isCircuitOpen() || !isRetryableError(error)) {
          throw lastError;
        }

        // Don't retry on last attempt
        if (attempt === this.config.maxRetries - 1) {
          throw lastError;
        }

        // Calculate delay and wait before retry
        const delay = calculateBackoffDelay(
          attempt,
          this.config.baseDelayMs,
          this.config.maxDelayMs
        );

        console.log(`Retrying request (attempt ${attempt + 1}/${this.config.maxRetries}) after ${delay}ms`);
        await this.sleep(delay);
      }
    }

    throw lastError!;
  }

  /**
   * Make a GET request with retry logic
   */
  async get<T>(path: string): Promise<T> {
    // Check circuit breaker
    if (this.isCircuitOpen()) {
      throw new Error('Circuit breaker is OPEN - service unavailable');
    }

    let lastError: Error;

    for (let attempt = 0; attempt < this.config.maxRetries; attempt++) {
      try {
        const response = await this.makeGetRequest<T>(path);
        this.onSuccess();
        return response;
      } catch (error) {
        lastError = error as Error;
        this.onFailure();

        if (this.isCircuitOpen() || !isRetryableError(error)) {
          throw lastError;
        }

        if (attempt === this.config.maxRetries - 1) {
          throw lastError;
        }

        const delay = calculateBackoffDelay(
          attempt,
          this.config.baseDelayMs,
          this.config.maxDelayMs
        );

        await this.sleep(delay);
      }
    }

    throw lastError!;
  }

  /**
   * Make actual HTTP request
   */
  private async makeRequest<T>(path: string, body: unknown): Promise<T> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeoutMs);

    try {
      const response = await fetch(`${this.config.baseUrl}${path}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Request-ID': crypto.randomUUID(),
        },
        body: JSON.stringify(body),
        signal: controller.signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => response.statusText);
        const error = new Error(errorText) as any;
        error.status = response.status;
        throw error;
      }

      return await response.json();
    } finally {
      clearTimeout(timeoutId);
    }
  }

  /**
   * Make GET request
   */
  private async makeGetRequest<T>(path: string): Promise<T> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeoutMs);

    try {
      const response = await fetch(`${this.config.baseUrl}${path}`, {
        method: 'GET',
        headers: {
          'X-Request-ID': crypto.randomUUID(),
        },
        signal: controller.signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => response.statusText);
        const error = new Error(errorText) as any;
        error.status = response.status;
        throw error;
      }

      return await response.json();
    } finally {
      clearTimeout(timeoutId);
    }
  }

  /**
   * Circuit breaker: check if circuit is open
   */
  private isCircuitOpen(): boolean {
    const now = Date.now();

    // Check if we should transition from OPEN to HALF_OPEN
    if (this.circuitBreaker.state === 'OPEN') {
      if (now - this.circuitBreaker.lastFailureTime > this.config.circuitBreakerResetMs) {
        this.circuitBreaker.state = 'HALF_OPEN';
        console.log('Circuit breaker transitioned to HALF_OPEN');
      }
    }

    return this.circuitBreaker.state === 'OPEN';
  }

  /**
   * Circuit breaker: record success
   */
  private onSuccess(): void {
    if (this.circuitBreaker.state === 'HALF_OPEN') {
      this.circuitBreaker.state = 'CLOSED';
      this.circuitBreaker.failures = 0;
      console.log('Circuit breaker transitioned to CLOSED');
    }
  }

  /**
   * Circuit breaker: record failure
   */
  private onFailure(): void {
    this.circuitBreaker.failures++;
    this.circuitBreaker.lastFailureTime = Date.now();

    if (this.circuitBreaker.failures >= this.config.circuitBreakerThreshold) {
      if (this.circuitBreaker.state !== 'OPEN') {
        this.circuitBreaker.state = 'OPEN';
        console.error(`Circuit breaker OPENED after ${this.circuitBreaker.failures} failures`);
      }
    }
  }

  /**
   * Sleep utility
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Reset circuit breaker (for testing or manual intervention)
   */
  resetCircuitBreaker(): void {
    this.circuitBreaker = {
      failures: 0,
      lastFailureTime: 0,
      state: 'CLOSED',
    };
    console.log('Circuit breaker reset to CLOSED');
  }
}

