/**
 * Schema Adapter
 * Bridges ExtendedFundModelInputs (new schema system) with legacy FundModelInputs
 *
 * This adapter allows incremental migration:
 * 1. New UI uses ExtendedFundModelInputs
 * 2. Adapter converts to legacy format
 * 3. Existing engine runs unchanged
 * 4. Later: Refactor engine to use ExtendedFundModelInputs directly
 */

import { Decimal } from 'decimal.js';
import type { ExtendedFundModelInputs } from '@shared/schemas/extended-fund-model';
import type { FundModelInputs, Stage } from '@shared/schemas/fund-model';
import type { StageType } from '@shared/schemas/stage-profile';

/**
 * Convert ExtendedFundModelInputs to legacy FundModelInputs
 *
 * Maps new schema fields to legacy format for backward compatibility.
 * Uses first fee tier and stage profile to populate legacy fields.
 */
export function adaptToLegacySchema(extended: ExtendedFundModelInputs): FundModelInputs {
  // Map stage types (new enum → legacy enum)
  const stageMap: Record<StageType, Stage> = {
    pre_seed: 'seed',
    seed: 'seed',
    series_a: 'series_a',
    series_b: 'series_b',
    series_c: 'series_c',
    growth: 'growth',
    late_stage: 'growth'
  };

  // Extract stage allocations from StageProfile
  const stageAllocations = extended.stageProfile.stages.map(stage => {
    // Calculate allocation as % of total portfolio
    const roundCapital = stage.roundSize.times(extended.stageProfile.initialPortfolioSize);
    const totalCapital = extended.stageProfile.stages.reduce(
      (sum, s) => sum.plus(s.roundSize.times(extended.stageProfile.initialPortfolioSize)),
      new Decimal(0)
    );
    const allocationPct = roundCapital.div(totalCapital).toNumber();

    return {
      stage: stageMap[stage.stage],
      allocationPct
    };
  });

  // Extract average check sizes
  const averageCheckSizes: Record<Stage, number> = {} as any;
  extended.stageProfile.stages.forEach(stage => {
    const legacyStage = stageMap[stage.stage];
    averageCheckSizes[legacyStage] = stage.roundSize.toNumber();
  });

  // Extract graduation rates (convert from cumulative to per-period if needed)
  const graduationRates: Record<Stage, number> = {} as any;
  extended.stageProfile.stages.forEach(stage => {
    const legacyStage = stageMap[stage.stage];
    graduationRates[legacyStage] = stage.graduationRate.toNumber();
  });

  // Extract exit rates
  const exitRates: Record<Stage, number> = {} as any;
  extended.stageProfile.stages.forEach(stage => {
    const legacyStage = stageMap[stage.stage];
    exitRates[legacyStage] = stage.exitRate.toNumber();
  });

  // Extract months to graduate/exit
  const monthsToGraduate: Record<Stage, number> = {} as any;
  const monthsToExit: Record<Stage, number> = {} as any;
  extended.stageProfile.stages.forEach(stage => {
    const legacyStage = stageMap[stage.stage];
    monthsToGraduate[legacyStage] = stage.monthsToGraduate;
    monthsToExit[legacyStage] = stage.monthsToExit;
  });

  // Extract management fee from first tier (legacy only supports single rate)
  const firstFeeTier = extended.feeProfile.tiers[0];
  const managementFeeRate = firstFeeTier?.annualRatePercent.toNumber() ?? 0.02;

  // Calculate reserve pool % from stage profile assumptions
  const reservePoolPct = extended.stageProfile.assumptions?.reserveStrategy === 'pro_rata'
    ? 0.3 // Default 30% for pro-rata
    : 0.4; // Default 40% for winner-picking

  return {
    fundSize: extended.committedCapital.toNumber(),
    periodLengthMonths: 3, // Default to quarterly (legacy hardcoded)
    capitalCallMode: 'upfront', // Legacy only supports upfront
    managementFeeRate,
    managementFeeYears: 10, // Default (can extract from fee profile tiers if needed)
    stageAllocations,
    reservePoolPct,
    averageCheckSizes,
    graduationRates,
    exitRates,
    monthsToGraduate,
    monthsToExit
  };
}

/**
 * Validate that ExtendedFundModelInputs can be safely converted to legacy format
 *
 * Returns array of warnings for features that won't be preserved in legacy format.
 */
export function validateLegacyCompatibility(extended: ExtendedFundModelInputs): string[] {
  const warnings: string[] = [];

  // Check for multi-tier fees
  if (extended.feeProfile.tiers.length > 1) {
    warnings.push(
      'Legacy engine only supports single fee tier. ' +
      `Only the first tier (${((extended.feeProfile.tiers[0]?.annualRatePercent.toNumber() ?? 0) * 100).toFixed(2)}%) will be used.`
    );
  }

  // Check for non-upfront capital calls
  if (extended.capitalCallPolicy.mode !== 'upfront') {
    warnings.push(
      `Legacy engine only supports upfront capital calls. ` +
      `${extended.capitalCallPolicy.mode} policy will be ignored.`
    );
  }

  // Check for waterfall policies
  if (extended.waterfallPolicy.type === 'american') {
    warnings.push(
      'Legacy engine uses simple immediate distribution (Policy A). ' +
      'American waterfall will not be applied.'
    );
  }

  // Check for recycling policies
  if (extended.recyclingPolicy?.enabled) {
    warnings.push(
      'Legacy engine does not support exit proceeds recycling. ' +
      'Recycling policy will be ignored.'
    );
  }

  // Check for fee recycling
  if (extended.feeProfile.recyclingPolicy?.enabled) {
    warnings.push(
      'Legacy engine does not support fee recycling. ' +
      'Fee recycling policy will be ignored.'
    );
  }

  // Check for fractional company counts
  if (!extended.stageProfile.initialPortfolioSize.isInteger()) {
    warnings.push(
      `Portfolio size is fractional (${extended.stageProfile.initialPortfolioSize.toString()}). ` +
      'Legacy engine will floor to integer, losing deterministic precision.'
    );
  }

  return warnings;
}

/**
 * Create a minimal ExtendedFundModelInputs from legacy FundModelInputs
 *
 * Useful for testing and backward compatibility.
 * Creates sensible defaults for new schema fields.
 */
export function adaptFromLegacySchema(legacy: FundModelInputs): ExtendedFundModelInputs {
  // Reverse stage mapping
  const stageTypeMap: Record<Stage, StageType> = {
    seed: 'seed',
    series_a: 'series_a',
    series_b: 'series_b',
    series_c: 'series_c',
    growth: 'growth'
  };

  // Calculate initial portfolio size from allocations
  const totalCompanies = legacy.stageAllocations.reduce((sum, alloc) => {
    const stageCapital = legacy.fundSize * alloc.allocationPct * (1 - legacy.reservePoolPct);
    const avgCheck = legacy.averageCheckSizes[alloc.stage] ?? 0;
    const numCompanies = avgCheck > 0 ? Math.floor(stageCapital / avgCheck) : 0;
    return sum + numCompanies;
  }, 0);

  return {
    // Base fields
    id: `legacy-${Date.now()}`,
    name: 'Legacy Fund Model',
    committedCapital: new Decimal(legacy.fundSize),
    fundTermMonths: 120, // Default 10 years
    vintageYear: new Date().getFullYear(),

    // Stage profile
    stageProfile: {
      id: 'legacy-stages',
      name: 'Legacy Stage Profile',
      initialPortfolioSize: new Decimal(totalCompanies),
      recyclingEnabled: false,

      stages: legacy.stageAllocations.map(alloc => ({
        stage: stageTypeMap[alloc.stage],
        roundSize: new Decimal(legacy.averageCheckSizes[alloc.stage] ?? 0),
        postMoneyValuation: new Decimal(legacy.averageCheckSizes[alloc.stage] ?? 0).times(5), // Heuristic: 5x check
        esopPercent: new Decimal(0.15), // Default 15%
        graduationRate: new Decimal(legacy.graduationRates[alloc.stage] ?? 0),
        exitRate: new Decimal(legacy.exitRates[alloc.stage] ?? 0),
        monthsToGraduate: legacy.monthsToGraduate[alloc.stage] ?? 24,
        monthsToExit: legacy.monthsToExit[alloc.stage] ?? 60,
        exitMultiple: new Decimal(3), // Default 3x
        dilutionPerRound: new Decimal(0.2) // Default 20%
      }))
    },

    // Fee profile (single tier from legacy)
    feeProfile: {
      id: 'legacy-fees',
      name: 'Legacy Fee Profile',
      tiers: [{
        basis: 'committed_capital',
        annualRatePercent: new Decimal(legacy.managementFeeRate),
        startYear: 1,
        endYear: legacy.managementFeeYears
      }],
      recyclingPolicy: undefined
    },

    // Capital call policy (upfront)
    capitalCallPolicy: {
      id: 'legacy-calls',
      name: 'Upfront Capital Call',
      mode: 'upfront',
      percentage: new Decimal(1),
      noticePeriodDays: 0,
      fundingPeriodDays: 0
    },

    // Waterfall policy (American for Policy A)
    waterfallPolicy: {
      id: 'legacy-waterfall',
      name: 'Simple American (Policy A)',
      type: 'american',
      preferredReturnRate: new Decimal(0), // No hurdle in legacy
      tiers: [
        { tierType: 'return_of_capital', priority: 1 },
        { tierType: 'carry', priority: 2, rate: new Decimal(0) } // No carry in legacy
      ],
      hurdleRateBasis: 'committed',
      cumulativeCalculations: true
    },

    // No recycling in legacy
    recyclingPolicy: undefined,

    // Default assumptions
    assumptions: {
      defaultHoldingPeriod: 60,
      reinvestmentPeriod: 36,
      portfolioConcentrationLimit: new Decimal(0.2),
      liquidateAtTermEnd: false,
      liquidationDiscountPercent: new Decimal(0.3)
    },

    // Monte Carlo disabled (legacy is deterministic)
    monteCarloSettings: {
      enabled: false,
      numberOfSimulations: 1,
      confidenceInterval: new Decimal(0.95)
    }
  };
}

/**
 * Intelligent Shadow Comparison Framework
 * Provides context-aware divergence analysis with business impact assessment
 */

import { metrics } from '@/metrics/reserves-metrics';
import type { ReservesResult } from '@shared/types/reserves-v11';

export type DivergenceType = 'rounding' | 'logic' | 'data' | 'error' | 'improvement';
export type Severity = 'critical' | 'warning' | 'info';

export interface DivergenceAnalysis {
  match: boolean;
  divergenceType: DivergenceType;
  severity: Severity;
  businessImpact: number; // Dollar amount of difference
  affectedCompanies: string[];
  conservationViolation: boolean;

  // Intelligent categorization
  isExpectedDivergence: boolean;
  requiresInvestigation: boolean;
  autoApprove: boolean;

  // Detailed breakdown
  details: {
    totalDifference: number;
    percentDifference: number;
    largestCompanyDiff: { id: string; amount: number };
    pattern: string; // e.g., "consistent_underallocation"
  };
}

export class ShadowIntelligence {
  private readonly ROUNDING_TOLERANCE = 1; // 1 cent
  private readonly CRITICAL_IMPACT_THRESHOLD = 1000; // $10
  private readonly WARNING_IMPACT_THRESHOLD = 100; // $1
  private readonly AUTO_APPROVE_THRESHOLD = 0.01; // 1 cent

  private patterns = new Map<string, number>();

  async analyzeDivergence(
    v1Result: ReservesResult,
    v11Result: ReservesResult
  ): Promise<DivergenceAnalysis> {
    const startTime = performance.now();

    try {
      // Quick match check
      if (this.exactMatch(v1Result, v11Result)) {
        return this.createMatchResult();
      }

      // Calculate business impact
      const impact = this.calculateBusinessImpact(v1Result, v11Result);

      // Determine divergence type
      const divergenceType = this.categorizeDivergence(v1Result, v11Result, impact);

      // Assess severity
      const severity = this.assessSeverity(impact, divergenceType);

      // Check conservation
      const conservationViolation = this.checkConservationViolation(v11Result);

      // Build analysis
      const analysis: DivergenceAnalysis = {
        match: false,
        divergenceType,
        severity,
        businessImpact: impact.totalDifference / 100, // Convert to dollars
        affectedCompanies: impact.affectedCompanies,
        conservationViolation,

        // Intelligent flags
        isExpectedDivergence: this.isExpectedImprovement(divergenceType, impact),
        requiresInvestigation: severity === 'critical' || conservationViolation,
        autoApprove: this.canAutoApprove(impact, divergenceType),

        details: {
          totalDifference: impact.totalDifference,
          percentDifference: impact.percentDifference,
          largestCompanyDiff: impact.largestDiff,
          pattern: this.detectPattern(v1Result, v11Result)
        }
      };

      // Record metrics
      this.recordAnalysis(analysis);

      // Alert if critical
      if (analysis.requiresInvestigation) {
        await this.triggerInvestigation(analysis);
      }

      return analysis;

    } finally {
      metrics.recordDuration('shadow.analysis', performance.now() - startTime);
    }
  }

  private exactMatch(v1: ReservesResult, v11: ReservesResult): boolean {
    if (!v1.ok || !v11.ok) return v1.ok === v11.ok;
    if (!v1.data || !v11.data) return false;

    // Check totals
    if (Math.abs(v1.data.remaining_cents - v11.data.remaining_cents) > this.ROUNDING_TOLERANCE) {
      return false;
    }

    // Check allocations
    const v1Map = new Map(v1.data.allocations.map(a => [a.company_id, a.planned_cents]));
    const v11Map = new Map(v11.data.allocations.map(a => [a.company_id, a.planned_cents]));

    if (v1Map.size !== v11Map.size) return false;

    for (const [id, v1Amount] of v1Map) {
      const v11Amount = v11Map['get'](id);
      if (!v11Amount || Math.abs(v1Amount - v11Amount) > this.ROUNDING_TOLERANCE) {
        return false;
      }
    }

    return true;
  }

  private calculateBusinessImpact(v1: ReservesResult, v11: ReservesResult) {
    const v1Allocations = v1.data?.allocations || [];
    const v11Allocations = v11.data?.allocations || [];

    const v1Map = new Map(v1Allocations.map(a => [a.company_id, a.planned_cents]));
    const v11Map = new Map(v11Allocations.map(a => [a.company_id, a.planned_cents]));

    let totalDifference = 0;
    const affectedCompanies: string[] = [];
    let largestDiff = { id: '', amount: 0 };

    // Check all companies
    const allCompanies = new Set([...v1Map.keys(), ...v11Map.keys()]);

    for (const companyId of allCompanies) {
      const v1Amount = v1Map['get'](companyId) || 0;
      const v11Amount = v11Map['get'](companyId) || 0;
      const diff = Math.abs(v11Amount - v1Amount);

      if (diff > this.ROUNDING_TOLERANCE) {
        totalDifference += diff;
        affectedCompanies.push(companyId);

        if (diff > largestDiff.amount) {
          largestDiff = { id: companyId, amount: diff };
        }
      }
    }

    const totalAllocated = v11.data?.metadata.total_allocated_cents || 1;
    const percentDifference = (totalDifference / totalAllocated) * 100;

    return {
      totalDifference,
      percentDifference,
      affectedCompanies,
      largestDiff
    };
  }

  private categorizeDivergence(
    v1: ReservesResult,
    v11: ReservesResult,
    impact: any
  ): DivergenceType {
    // Rounding differences
    if (impact.totalDifference <= this.ROUNDING_TOLERANCE * impact.affectedCompanies.length) {
      return 'rounding';
    }

    // Error in one engine
    if (v1.ok !== v11.ok) {
      return 'error';
    }

    // Data differences (different company counts)
    if (v1.data?.allocations.length !== v11.data?.allocations.length) {
      return 'data';
    }

    // Check if v11 is consistently better (improvement)
    if (this.isConsistentImprovement(v1, v11)) {
      return 'improvement';
    }

    // Logic differences
    return 'logic';
  }

  private assessSeverity(impact: any, type: DivergenceType): Severity {
    // Critical: Large business impact or errors
    if (impact.totalDifference > this.CRITICAL_IMPACT_THRESHOLD * 100 || type === 'error') {
      return 'critical';
    }

    // Warning: Medium impact or data differences
    if (impact.totalDifference > this.WARNING_IMPACT_THRESHOLD * 100 || type === 'data') {
      return 'warning';
    }

    // Info: Small impact, rounding, or improvements
    return 'info';
  }

  private checkConservationViolation(result: ReservesResult): boolean {
    if (!result.ok || !result.data) return false;
    return !result.data.metadata.conservation_check;
  }

  private isExpectedImprovement(type: DivergenceType, impact: any): boolean {
    // Improvements are expected
    if (type === 'improvement') return true;

    // Small rounding differences are expected
    if (type === 'rounding' && impact.totalDifference < 10) return true;

    return false;
  }

  private canAutoApprove(impact: any, type: DivergenceType): boolean {
    // Auto-approve tiny differences
    if (impact.totalDifference <= this.AUTO_APPROVE_THRESHOLD) return true;

    // Auto-approve known improvements
    if (type === 'improvement' && impact.totalDifference < this.WARNING_IMPACT_THRESHOLD) {
      return true;
    }

    // Auto-approve rounding differences
    if (type === 'rounding' && impact.percentDifference < 0.01) {
      return true;
    }

    return false;
  }

  private isConsistentImprovement(v1: ReservesResult, v11: ReservesResult): boolean {
    if (!v1.data || !v11.data) return false;

    // Check if v11 has better utilization
    const v1Utilization = v1.data.metadata.total_allocated_cents / v1.data.metadata.total_available_cents;
    const v11Utilization = v11.data.metadata.total_allocated_cents / v11.data.metadata.total_available_cents;

    return v11Utilization > v1Utilization && v11.data.metadata.conservation_check;
  }

  private detectPattern(v1: ReservesResult, v11: ReservesResult): string {
    // Detect common patterns
    if (!v1.data || !v11.data) return 'error_pattern';

    const v1Total = v1.data.metadata.total_allocated_cents;
    const v11Total = v11.data.metadata.total_allocated_cents;

    if (v11Total > v1Total) return 'increased_allocation';
    if (v11Total < v1Total) return 'decreased_allocation';
    if (v11.data.allocations.length > v1.data.allocations.length) return 'morecompanies_funded';
    if (v11.data.allocations.length < v1.data.allocations.length) return 'fewercompanies_funded';

    return 'rebalanced_allocation';
  }

  private createMatchResult(): DivergenceAnalysis {
    return {
      match: true,
      divergenceType: 'rounding',
      severity: 'info',
      businessImpact: 0,
      affectedCompanies: [],
      conservationViolation: false,
      isExpectedDivergence: false,
      requiresInvestigation: false,
      autoApprove: true,
      details: {
        totalDifference: 0,
        percentDifference: 0,
        largestCompanyDiff: { id: '', amount: 0 },
        pattern: 'exact_match'
      }
    };
  }

  private recordAnalysis(analysis: DivergenceAnalysis): void {
    // Record pattern frequency
    const pattern = analysis.details.pattern;
    this.patterns['set'](pattern, (this.patterns['get'](pattern) || 0) + 1);

    // Record metrics
    metrics.recordDivergence(analysis.divergenceType, analysis.severity);

    // Log for analysis
    if (analysis.severity !== 'info') {
      console.log('Shadow divergence detected:', analysis);
    }
  }

  private async triggerInvestigation(analysis: DivergenceAnalysis): Promise<void> {
    // Send alert
    const alert = {
      type: 'shadow_divergence',
      severity: analysis.severity,
      businessImpact: analysis.businessImpact,
      pattern: analysis.details.pattern,
      requiresAction: analysis.requiresInvestigation,
      timestamp: new Date().toISOString()
    };

    // Send to monitoring
    if (typeof navigator !== 'undefined' && navigator.sendBeacon) {
      const alertUrl = document.querySelector('meta[name="alert-url"]')?.getAttribute('content');
      if (alertUrl) {
        navigator.sendBeacon(alertUrl, JSON.stringify(alert));
      }
    }
  }

  // Get pattern insights
  getPatternInsights(): Map<string, number> {
    return new Map(this.patterns);
  }

  // Clear pattern history
  clearPatterns(): void {
    this.patterns.clear();
  }
}

// Export singleton
export const shadowIntelligence = new ShadowIntelligence();

