  const handleRecyclingToggle = (enabled: boolean) => {
    updateDistributions({
      recyclingEnabled: enabled,
      // Reset recycling values when disabled
      exitRecyclingRate: enabled ? exitRecyclingRate : 0,
      mgmtFeeRecyclingRate: enabled ? mgmtFeeRecyclingRate : 0
