                                placeholder="2.0"
                                className="h-12 border-[#E0D8D1] focus:border-[#292929] focus:ring-[#292929] font-poppins"
                              />
                            </div>

                            <div className="space-y-3">
                              <Label className="text-sm font-poppins font-medium text-[#292929]">Fee Basis</Label>
                              <Select
                                value={tier.feeBasis}
