                              monthlyAmount: parseFloat(e.target.value) || 0
                            })}
                            placeholder="10000"
                            className="h-12 border-[#E0D8D1] focus:border-[#292929] focus:ring-[#292929] font-poppins"
                          />
                        </div>

                        <div className="space-y-3">
