          <TabsTrigger value="timeline">Timeline View</TabsTrigger>
          <TabsTrigger value="snapshots">Snapshot Manager</TabsTrigger>
          <TabsTrigger value="comparison">State Comparison</TabsTrigger>
          <TabsTrigger value="playback">Time Playback</TabsTrigger>
        </TabsList>

        <TabsContent value="timeline" className="space-y-6">
          {/* Time Range Selector */}
          <Card>
            <CardHeader>
              <CardTitle>Time Range Selection</CardTitle>
              <CardDescription>
                Select the time range for timeline analysis
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="flex items-center space-x-4">
                <div className="flex items-center space-x-2">
                  <label className="text-sm font-medium">Start Date:</label>
                  <Input
                    type="date"
                    value={selectedTimeRange.start}
                    onChange={(e) => setSelectedTimeRange(prev => ({ ...prev, start: e.target.value }))}
                    className="w-40"
                  />
                </div>
                <div className="flex items-center space-x-2">
                  <label className="text-sm font-medium">End Date:</label>
                  <Input
                    type="date"
                    value={selectedTimeRange.end}
                    onChange={(e) => setSelectedTimeRange(prev => ({ ...prev, end: e.target.value }))}
                    className="w-40"
                  />
                </div>
                <Button
                  onClick={() => refetchTimeline()}
                  variant="outline"
                  className="flex items-center space-x-2"
                >
                  <History className="w-4 h-4" />
                  <span>Update Timeline</span>
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Timeline Visualizations */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <TimelineChart
              data={timelineChartData}
              title="Event Timeline"
              description="Timeline of fund events and activities"
              loading={timelineLoading}
              height={400}
            />

            <EventTimelineChart
              events={snapshotEvents}
              title="Snapshot Timeline"
              description="Available fund snapshots over time"
              height={400}
            />
          </div>

          {/* Event List */}
          <Card>
            <CardHeader>
              <CardTitle>Recent Events</CardTitle>
              <CardDescription>
                Detailed list of fund events in the selected time range
              </CardDescription>
            </CardHeader>
            <CardContent>
              {timelineLoading ? (
                <div className="space-y-4">
                  {Array.from({ length: 5 }).map((_, i) => (
                    <div key={i} className="animate-pulse flex items-center space-x-4 p-4 border rounded-lg">
                      <div className="w-10 h-10 bg-gray-200 rounded-full" />
                      <div className="flex-1 space-y-2">
                        <div className="h-4 w-3/4 bg-gray-200 rounded" />
                        <div className="h-3 w-1/2 bg-gray-200 rounded" />
                      </div>
                    </div>
                  ))}
                </div>
              ) : timelineData?.events?.length ? (
                <div className="space-y-2 max-h-96 overflow-y-auto">
                  {timelineData.events.slice(0, 20).map((event) => (
                    <div
                      key={event.id}
                      className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50"
                    >
                      <div className="flex items-center space-x-4">
                        <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                          <Activity className="w-5 h-5 text-blue-600" />
                        </div>
                        <div>
                          <div className="font-medium text-gray-900">{event.eventType}</div>
                          <div className="text-sm text-gray-600">
                            {event.operation} • {event.entityType}
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="text-sm font-medium text-gray-900">
                          {format(parseISO(event.eventTime), 'MMM dd, yyyy')}
                        </div>
                        <div className="text-xs text-gray-500">
                          {format(parseISO(event.eventTime), 'HH:mm:ss')}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-500">
                  No events found in the selected time range
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="snapshots" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Snapshot Management</CardTitle>
              <CardDescription>
                Create, manage, and restore fund snapshots
              </CardDescription>
            </CardHeader>
            <CardContent>
              {timelineLoading ? (
                <div className="space-y-4">
                  {Array.from({ length: 3 }).map((_, i) => (
                    <div key={i} className="animate-pulse flex items-center justify-between p-4 border rounded-lg">
                      <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 bg-gray-200 rounded-lg" />
                        <div className="space-y-2">
                          <div className="h-4 w-48 bg-gray-200 rounded" />
                          <div className="h-3 w-32 bg-gray-200 rounded" />
                        </div>
                      </div>
                      <div className="w-24 h-8 bg-gray-200 rounded" />
                    </div>
                  ))}
                </div>
              ) : timelineData?.snapshots?.length ? (
                <div className="space-y-4">
                  {timelineData.snapshots.map((snapshot) => (
                    <div
                      key={snapshot.id}
                      className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50"
                    >
                      <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center">
                          <Camera className="w-6 h-6 text-green-600" />
                        </div>
                        <div>
                          <div className="font-medium text-gray-900">
                            Snapshot {snapshot.id}
                          </div>
                          <div className="text-sm text-gray-600">
                            {format(parseISO(snapshot.snapshotTime), 'MMM dd, yyyy HH:mm')}
                          </div>
                          <Badge variant="outline" className="mt-1">
                            {snapshot.eventCount} events
                          </Badge>
                        </div>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setCurrentViewTime(snapshot.snapshotTime)}
                        >
                          View State
                        </Button>
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              variant="outline"
                              size="sm"
                              className="text-orange-600 border-orange-200 hover:bg-orange-50"
                              onClick={() => setSelectedSnapshotId(snapshot.id)}
                            >
                              <RotateCcw className="w-4 h-4 mr-1" />
                              Restore
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent>
                            <AlertDialogHeader>
                              <AlertDialogTitle>Restore Fund State</AlertDialogTitle>
                              <AlertDialogDescription>
                                This will restore your fund to the state captured in Snapshot {snapshot.id}.
                                This action cannot be undone. Please enter the confirmation code to proceed.
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <div className="my-4">
                              <Input
                                placeholder="Enter confirmation code"
                                value={confirmationCode}
                                onChange={(e) => setConfirmationCode(e.target.value)}
                              />
                            </div>
                            <AlertDialogFooter>
                              <AlertDialogCancel onClick={() => {
                                setSelectedSnapshotId(null);
                                setConfirmationCode('');
                              }}>
                                Cancel
                              </AlertDialogCancel>
                              <AlertDialogAction
                                onClick={handleRestoreSnapshot}
                                disabled={!confirmationCode.trim() || restoreSnapshotMutation.isPending}
                                className="bg-orange-600 hover:bg-orange-700"
                              >
                                {restoreSnapshotMutation.isPending ? 'Restoring...' : 'Restore State'}
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <Camera className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <h3 className="text-lg font-medium text-gray-900 mb-2">No Snapshots</h3>
                  <p className="text-gray-600 mb-4">
                    Create your first snapshot to save the current fund state.
                  </p>
                  <Button onClick={() => setCreateSnapshotDialogOpen(true)}>
                    Create First Snapshot
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="comparison" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>State Comparison</CardTitle>
              <CardDescription>
                Compare fund states between two different points in time
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Timestamp Selection */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-medium">First Timestamp</label>
                  <Input
                    type="datetime-local"
                    value={selectedTimestamp1}
                    onChange={(e) => setSelectedTimestamp1(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Second Timestamp</label>
                  <Input
                    type="datetime-local"
                    value={selectedTimestamp2}
                    onChange={(e) => setSelectedTimestamp2(e.target.value)}
                  />
                </div>
              </div>

              {/* Comparison Results */}
              {comparisonLoading ? (
                <div className="animate-pulse space-y-4">
                  <div className="h-8 w-64 bg-gray-200 rounded" />
                  <div className="h-32 w-full bg-gray-200 rounded" />
                </div>
              ) : comparisonData && selectedTimestamp1 && selectedTimestamp2 ? (
                <div className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <StatCard
                      title="Total Changes"
                      value={comparisonData.summary.totalChanges}
                      icon={GitBranch}
                    />
                    <StatCard
                      title="Time Span"
                      value={`${Math.round(comparisonData.summary.timeSpan / (1000 * 60 * 60))}h`}
                      icon={Clock}
                    />
                    <StatCard
                      title="State Snapshots"
                      value="2"
                      icon={Camera}
                    />
                  </div>

                  {comparisonData.differences && comparisonData.differences.length > 0 ? (
                    <Card>
                      <CardHeader>
                        <CardTitle>Detected Changes</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2">
                          {comparisonData.differences.map((diff, index) => (
                            <div key={index} className="p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
                              <div className="font-medium text-yellow-800">
                                Change {index + 1}
                              </div>
                              <div className="text-sm text-yellow-700 mt-1">
                                {typeof diff === 'object' ? JSON.stringify(diff) : diff}
                              </div>
                            </div>
                          ))}
                        </div>
                      </CardContent>
                    </Card>
                  ) : (
                    <Card>
                      <CardContent className="text-center py-8">
                        <div className="text-green-600 mb-2">
                          <GitBranch className="w-8 h-8 mx-auto" />
                        </div>
                        <h3 className="font-medium text-gray-900">No Changes Detected</h3>
                        <p className="text-gray-600 text-sm">
                          The fund states are identical between these two timestamps.
                        </p>
                      </CardContent>
                    </Card>
                  )}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-500">
                  Select two timestamps to compare fund states
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="playback" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Time Playback</CardTitle>
              <CardDescription>
                Step through time to see how your fund evolved
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Playback Controls */}
              <div className="flex items-center justify-center space-x-4">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    if (currentViewTime) {
                      const newTime = subDays(parseISO(currentViewTime), 1).toISOString();
                      setCurrentViewTime(newTime);
                    }
                  }}
                >
                  <ChevronLeft className="w-4 h-4" />
                </Button>

                <Button
                  variant={isPlaying ? "secondary" : "default"}
                  onClick={() => setIsPlaying(!isPlaying)}
                  className="flex items-center space-x-2"
                >
                  {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
                  <span>{isPlaying ? 'Pause' : 'Play'}</span>
                </Button>

                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    if (currentViewTime) {
                      const newTime = addDays(parseISO(currentViewTime), 1).toISOString();
                      setCurrentViewTime(newTime);
                    }
                  }}
                >
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>

              {/* Speed Control */}
              <div className="flex items-center justify-center space-x-4">
                <span className="text-sm text-gray-600">Speed:</span>
                <Select value={playbackSpeed.toString()} onValueChange={(value) => setPlaybackSpeed(parseFloat(value))}>
                  <SelectTrigger className="w-24">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="0.5">0.5x</SelectItem>
                    <SelectItem value="1">1x</SelectItem>
                    <SelectItem value="2">2x</SelectItem>
                    <SelectItem value="5">5x</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Current Time Display */}
              <div className="text-center">
                <div className="text-lg font-medium text-gray-900">
                  {currentViewTime ? format(parseISO(currentViewTime), 'MMMM dd, yyyy HH:mm') : 'Select a time to view'}
                </div>
              </div>

              {/* Point in Time State */}
              {pointInTimeLoading ? (
                <div className="animate-pulse space-y-4">
                  <div className="h-8 w-48 bg-gray-200 rounded mx-auto" />
                  <div className="h-32 w-full bg-gray-200 rounded" />
                </div>
              ) : pointInTimeData ? (
                <Card>
                  <CardHeader>
                    <CardTitle>Fund State</CardTitle>
                    <CardDescription>
                      State as of {format(parseISO(pointInTimeData.timestamp), 'MMMM dd, yyyy HH:mm')}
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <StatCard
                        title="Snapshot ID"
                        value={pointInTimeData.snapshot.id}
                        icon={Camera}
                      />
                      <StatCard
                        title="Event Count"
                        value={pointInTimeData.snapshot.eventCount}
                        icon={Activity}
                      />
                      <StatCard
                        title="Events Applied"
                        value={pointInTimeData.eventsApplied}
                        icon={Zap}
                      />
                    </div>

                    {pointInTimeData.state && (
                      <div className="mt-6">
                        <h4 className="font-medium text-gray-900 mb-2">State Data</h4>
                        <pre className="bg-gray-50 p-4 rounded-lg text-sm overflow-auto max-h-64">
                          {JSON.stringify(pointInTimeData.state, null, 2)}
                        </pre>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ) : currentViewTime ? (
                <div className="text-center py-8 text-gray-500">
                  No state data available for the selected time
                </div>
              ) : null}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useFundContext } from '@/contexts/FundContext';
import {
  useVarianceDashboard,
  useBaselines,
  useActiveAlerts,
  useVarianceReports,
  useCreateBaseline,
  useSetDefaultBaseline,
  useDeactivateBaseline,
  useGenerateVarianceReport,
  useCreateAlertRule,
  useAcknowledgeAlert,
  useResolveAlert,
  usePerformVarianceAnalysis,
  type Alert,
  type Baseline
} from '@/hooks/useVarianceData';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { cn } from '@/lib/utils';
import {
  DashboardLoadingState,
  ErrorState,
  ApiErrorState,
  StatCard,
  StatCardGrid,
  VarianceChart
} from '@/components/analytics';
import {
  AlertTriangle,
  Plus,
  TrendingUp,
  Bell,
  CheckCircle,
  XCircle,
  Target,
  Clock,
  AlertCircle,
  FileText,
  Zap
} from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { toast } from '@/hooks/use-toast';
import { spreadIfDefined } from '@/lib/ts/spreadIfDefined';

export default function VarianceTrackingPage() {
  const { currentFund } = useFundContext();
  const [createBaselineDialogOpen, setCreateBaselineDialogOpen] = useState(false);
  const [createAlertDialogOpen, setCreateAlertDialogOpen] = useState(false);
  const [generateReportDialogOpen, setGenerateReportDialogOpen] = useState(false);
  const [selectedAlert, setSelectedAlert] = useState<Alert | null>(null);
  const [alertActionDialogOpen, setAlertActionDialogOpen] = useState(false);
  const [actionType, setActionType] = useState<'acknowledge' | 'resolve'>('acknowledge');
  const [actionNotes, setActionNotes] = useState('');

  // Form states
  const [baselineForm, setBaselineForm] = useState({
    name: '',
    description: '',
    baselineType: 'quarterly' as 'initial' | 'quarterly' | 'annual' | 'milestone' | 'custom',
    periodStart: '',
    periodEnd: '',
    tags: [] as string[]
  });

  const [alertRuleForm, setAlertRuleForm] = useState({
    name: '',
    description: '',
    ruleType: 'threshold' as 'threshold' | 'trend' | 'deviation' | 'pattern',
    metricName: '',
    operator: 'gt' as 'gt' | 'lt' | 'eq' | 'gte' | 'lte' | 'between',
    thresholdValue: 0,
    secondaryThreshold: undefined as number | undefined,
    severity: 'warning' as 'info' | 'warning' | 'critical' | 'urgent',
    category: 'performance' as 'performance' | 'risk' | 'operational' | 'compliance',
    checkFrequency: 'daily' as 'realtime' | 'hourly' | 'daily' | 'weekly'
  });

  const [reportForm, setReportForm] = useState({
    baselineId: '',
    reportName: '',
    reportType: 'ad_hoc' as 'periodic' | 'milestone' | 'ad_hoc' | 'alert_triggered',
    reportPeriod: undefined as 'monthly' | 'quarterly' | 'annual' | undefined,
    asOfDate: ''
  });

  // Hooks
  const {
    data: dashboardData,
    isLoading: dashboardLoading,
    error: dashboardError,
    refetch: refetchDashboard
  } = useVarianceDashboard(currentFund?.id || 0);

  const {
    data: baselinesData,
    isLoading: baselinesLoading,
    error: baselinesError,
    refetch: refetchBaselines
  } = useBaselines(currentFund?.id || 0);

  const {
    data: alertsData,
    isLoading: alertsLoading,
    error: alertsError,
    refetch: refetchAlerts
  } = useActiveAlerts(currentFund?.id || 0);

  const {
    data: reportsData,
    isLoading: reportsLoading,
    error: reportsError
  } = useVarianceReports(currentFund?.id || 0);

  // Mutations
  const createBaselineMutation = useCreateBaseline();
  const setDefaultBaselineMutation = useSetDefaultBaseline();
  const deactivateBaselineMutation = useDeactivateBaseline();
  const generateReportMutation = useGenerateVarianceReport();
  const createAlertRuleMutation = useCreateAlertRule();
  const acknowledgeAlertMutation = useAcknowledgeAlert();
  const resolveAlertMutation = useResolveAlert();
  const performAnalysisMutation = usePerformVarianceAnalysis();

  // Mock variance data for demonstration
  const mockVarianceData = useMemo(() => [
    {
      metric: 'IRR Target',
      baseline: 25.0,
      actual: 22.5,
      variance: -2.5,
      variancePercent: -10.0,
      severity: 'medium' as const
    },
    {
      metric: 'Management Fee',
      baseline: 2.0,
      actual: 2.1,
      variance: 0.1,
      variancePercent: 5.0,
      severity: 'low' as const
    },
    {
      metric: 'Portfolio Size',
      baseline: 100,
      actual: 95,
      variance: -5,
      variancePercent: -5.0,
      severity: 'low' as const
    },
    {
      metric: 'Deployment Rate',
      baseline: 80.0,
      actual: 65.0,
      variance: -15.0,
      variancePercent: -18.75,
      severity: 'high' as const
    }
  ], []);

  // Handle baseline creation
  const handleCreateBaseline = async () => {
    if (!currentFund) return;

    try {
      await createBaselineMutation.mutateAsync({
        fundId: currentFund.id,
        ...baselineForm
      });

      toast({
        title: "Baseline Created",
        description: "New baseline has been created successfully.",
      });

      setCreateBaselineDialogOpen(false);
      setBaselineForm({
        name: '',
        description: '',
        baselineType: 'quarterly',
        periodStart: '',
        periodEnd: '',
        tags: []
      });
      refetchBaselines();
      refetchDashboard();
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to create baseline. Please try again.",
        variant: "destructive",
      });
    }
  };

  // Handle alert rule creation
  const handleCreateAlertRule = async () => {
    if (!currentFund) return;

    try {
      await createAlertRuleMutation.mutateAsync({
        fundId: currentFund.id,
        name: alertRuleForm.name,
        description: alertRuleForm.description,
        ruleType: alertRuleForm.ruleType,
        metricName: alertRuleForm.metricName,
        operator: alertRuleForm.operator,
        thresholdValue: alertRuleForm.thresholdValue,
        severity: alertRuleForm.severity,
        category: alertRuleForm.category,
        checkFrequency: alertRuleForm.checkFrequency,
        ...spreadIfDefined('secondaryThreshold', alertRuleForm.secondaryThreshold)
      });

      toast({
        title: "Alert Rule Created",
        description: "New alert rule has been created successfully.",
      });

      setCreateAlertDialogOpen(false);
      setAlertRuleForm({
        name: '',
        description: '',
        ruleType: 'threshold',
        metricName: '',
        operator: 'gt',
        thresholdValue: 0,
        secondaryThreshold: undefined,
        severity: 'warning',
        category: 'performance',
        checkFrequency: 'daily'
      });
      refetchAlerts();
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to create alert rule. Please try again.",
        variant: "destructive",
      });
    }
  };

  // Handle alert actions
  const handleAlertAction = async () => {
    if (!selectedAlert) return;

    try {
      if (actionType === 'acknowledge') {
        await acknowledgeAlertMutation.mutateAsync({
          alertId: selectedAlert.id,
          notes: actionNotes
        });
        toast({
          title: "Alert Acknowledged",
          description: "The alert has been acknowledged.",
        });
      } else {
        await resolveAlertMutation.mutateAsync({
          alertId: selectedAlert.id,
          notes: actionNotes
        });
        toast({
          title: "Alert Resolved",
          description: "The alert has been resolved.",
        });
      }

      setAlertActionDialogOpen(false);
      setSelectedAlert(null);
      setActionNotes('');
      refetchAlerts();
      refetchDashboard();
    } catch (error) {
      toast({
        title: "Error",
        description: `Failed to ${actionType} alert. Please try again.`,
        variant: "destructive",
      });
    }
  };

  // Handle variance analysis
  const handlePerformAnalysis = async () => {
    if (!currentFund) return;

    try {
      const result = await performAnalysisMutation.mutateAsync({
        fundId: currentFund.id
      });

      toast({
        title: "Analysis Complete",
        description: `Variance analysis completed. ${result.data.alertCount} alerts generated.`,
      });

      refetchDashboard();
      refetchAlerts();
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to perform variance analysis. Please try again.",
        variant: "destructive",
      });
    }
  };

  if (!currentFund) {
    return (
      <div className="container mx-auto p-6">
        <ErrorState
          title="No Fund Selected"
          message="Please select a fund to view variance tracking."
          onGoHome={() => window.location.href = '/fund-setup'}
        />
      </div>
    );
  }

  if (dashboardError) {
    return (
      <div className="container mx-auto p-6">
