/**
 * Zod schemas for runtime validation of reserves data
 * Ensures type safety and data integrity at runtime boundaries
 */

import { z } from 'zod';
import { nonNegative, bounded01, positiveInt, yearRange } from '@shared/schema-helpers';
import {
  dollarsToCentsValidated as dollarsToCentsCore,
  percentToBpsValidated as percentToBpsCore
} from '@/lib/units';

// Company schema with validation rules
export const CompanySchema = z.object({
  id: z.string().min(1, 'Company ID is required'),
  name: z.string().min(1, 'Company name is required'),
  invested_cents: z.number()
    .int('Investment must be in integer cents')
    .nonnegative('Investment cannot be negative')
    .max(Number.MAX_SAFE_INTEGER, 'Investment exceeds maximum safe integer'),
  exit_moic_bps: z.number()
    .int('Exit MOIC must be in basis points')
    .nonnegative('Exit MOIC cannot be negative')
    .max(1000000, 'Exit MOIC exceeds reasonable bounds (100x)'),
  stage: z.string().optional(),
  sector: z.string().optional(),
  ownership_pct: bounded01().optional(),
  metadata: z.record(z.unknown()).optional()
}).strict();

// Cap policy schemas
export const FixedCapPolicySchema = z.object({
  kind: z.literal('fixed_percent'),
  default_percent: z.number()
    .min(0, 'Cap percentage cannot be negative')
    .max(10, 'Cap percentage exceeds reasonable bounds (1000%)')
    .optional()
}).strict();

export const StageBasedCapPolicySchema = z.object({
  kind: z.literal('stage_based'),
  default_percent: z.number()
    .min(0, 'Default cap percentage cannot be negative')
    .max(10, 'Default cap percentage exceeds reasonable bounds')
    .optional(),
  stage_caps: z.record(
    z.string(),
    nonNegative().max(10)
  ).optional()
}).strict();

export const CustomCapPolicySchema = z.object({
  kind: z.literal('custom'),
  custom_fn: z.function()
    .args(CompanySchema)
    .returns(z.number())
    .optional()
}).strict();

export const CapPolicySchema = z.discriminatedUnion('kind', [
  FixedCapPolicySchema,
  StageBasedCapPolicySchema,
  CustomCapPolicySchema
]);

// Reserves configuration schema
export const ReservesConfigSchema = z.object({
  reserve_bps: z.number()
    .int('Reserve percentage must be in basis points')
    .min(0, 'Reserve percentage cannot be negative')
    .max(10000, 'Reserve percentage cannot exceed 100%'),
  remain_passes: z.union([z.literal(0), z.literal(1)]),
  cap_policy: CapPolicySchema,
  audit_level: z.enum(['basic', 'detailed', 'debug'])
}).strict();

// Reserves input schema
export const ReservesInputSchema = z.object({
  companies: z.array(CompanySchema)
    .min(0, 'Companies array cannot be null')
    .max(10000, 'Too many companies (max 10,000)'),
  fund_size_cents: z.number()
    .int('Fund size must be in integer cents')
    .nonnegative('Fund size cannot be negative')
    .max(Number.MAX_SAFE_INTEGER, 'Fund size exceeds maximum safe integer'),
  quarter_index: yearRange(1900 * 4, 2100 * 4 + 3)
}).strict();

// Allocation decision schema
export const AllocationDecisionSchema = z.object({
  company_id: z.string().min(1),
  planned_cents: z.number()
    .int()
    .nonnegative()
    .max(Number.MAX_SAFE_INTEGER),
  reason: z.string(),
  cap_cents: z.number()
    .int()
    .nonnegative(),
  iteration: positiveInt().max(10)
}).strict();

// Reserves output schema
export const ReservesOutputSchema = z.object({
  allocations: z.array(AllocationDecisionSchema),
  remaining_cents: z.number()
    .int()
    .nonnegative(),
  metadata: z.object({
    total_available_cents: z.number().int().nonnegative(),
    total_allocated_cents: z.number().int().nonnegative(),
    companies_funded: z.number().int().nonnegative(),
    max_iterations: z.number().int().positive(),
    conservation_check: z.boolean(),
    exit_moic_ranking: z.array(z.string())
  }).strict()
}).strict();

// Reserves result schema
export const ReservesResultSchema = z.object({
  ok: z.boolean(),
  data: ReservesOutputSchema.optional(),
  error: z.string().optional(),
  warnings: z.array(z.string()).optional(),
  metrics: z.object({
    duration_ms: z.number().nonnegative(),
    company_count: z.number().int().nonnegative(),
    policy_type: z.string()
  }).strict().optional()
}).strict();

// Type exports
export type Company = z.infer<typeof CompanySchema>;
export type ReservesConfig = z.infer<typeof ReservesConfigSchema>;
export type ReservesInput = z.infer<typeof ReservesInputSchema>;
export type ReservesOutput = z.infer<typeof ReservesOutputSchema>;
export type ReservesResult = z.infer<typeof ReservesResultSchema>;

// Validation helpers
export function validateCompany(data: unknown): Company {
  return CompanySchema.parse(data);
}

export function validateCompanies(data: unknown[]): Company[] {
  return z.array(CompanySchema).parse(data);
}

export function validateConfig(data: unknown): ReservesConfig {
  return ReservesConfigSchema.parse(data);
}

export function validateInput(data: unknown): ReservesInput {
  return ReservesInputSchema.parse(data);
}

export function validateOutput(data: unknown): ReservesOutput {
  return ReservesOutputSchema.parse(data);
}

export function validateResult(data: unknown): ReservesResult {
  return ReservesResultSchema.parse(data);
}

// Safe validation with error handling
export function safeValidateCompany(data: unknown): { success: true; data: Company } | { success: false; error: z.ZodError } {
  const result = CompanySchema.safeParse(data);
  if (result.success) {
    return { success: true, data: result.data };
  } else {
    return { success: false, error: result.error };
  }
}

export function safeValidateConfig(data: unknown): { success: true; data: ReservesConfig } | { success: false; error: z.ZodError } {
  const result = ReservesConfigSchema.safeParse(data);
  if (result.success) {
    return { success: true, data: result.data };
  } else {
    return { success: false, error: result.error };
  }
}

// Adapter with validation
export function adaptAndValidateCompanies(rawData: unknown[]): {
  valid: Company[];
  invalid: Array<{ index: number; errors: string[] }>;
} {
  const valid: Company[] = [];
  const invalid: Array<{ index: number; errors: string[] }> = [];

  rawData.forEach((item: any, index: any) => {
    const result = CompanySchema.safeParse(item);
    if (result.success) {
      valid.push(result.data);
    } else {
      invalid.push({
        index,
        errors: result.error.errors.map(e => `${e.path.join('.')}: ${e.message}`)
      });
    }
  });

  return { valid, invalid };
}

// Money utilities with validation (wraps centralized units.ts with Zod validation)
export function dollarsToCentsValidated(dollars: unknown): number {
  const parsed = z.number().safeParse(dollars);
  if (!parsed.success) return 0;

  // Delegate to centralized units.ts (enforces precision rules)
  try {
    return dollarsToCentsCore(parsed.data);
  } catch {
    // If validation fails, return 0 (backward compatibility)
    return 0;
  }
}

export function percentToBpsValidated(percent: unknown): number {
  const parsed = z.number().safeParse(percent);
  if (!parsed.success) return 0;

  // Delegate to centralized units.ts (enforces precision rules)
  try {
    return percentToBpsCore(parsed.data);
  } catch {
    // If validation fails, clamp to valid range
    const value = parsed.data;
    if (value < 0) return 0;
    if (value > 100) return 10000;
    return Math.round(value * 100);
  }
}

// Pure builder used by Step 3 – no hooks, no set(), no side effects
export type StrategyInputs = {
  stages: Array<{
    id: string;
    name: string;
    graduate: number;
    exit: number;
    months: number;
  }>;
  sectorProfiles: Array<{
    id: string;
    name: string;
    targetPercentage: number;
    description: string;
  }>;
  allocations: Array<{
    id: string;
    category: string;
    percentage: number;
    description: string;
  }>;
};

export type InvestmentStrategy = {
  stages: Array<{
    id: string;
    name: string;
    graduationRate: number;
    exitRate: number;
    remainRate: number;
  }>;
  sectorProfiles: Array<{
    id: string;
    name: string;
    targetPercentage: number;
    description: string;
  }>;
  allocations: Array<{
    id: string;
    category: string;
    percentage: number;
    description: string;
  }>;
  totalSectorAllocation: number;
  totalAllocation: number;
  validation: {
    stages: Array<string | null>;
    sectors: Array<string | null>;
    allocations: Array<string | null>;
    allValid: boolean;
  };
};

// Defensive input validation
function validateInputs(inputs: StrategyInputs): boolean {
  if (!inputs || typeof inputs !== 'object') return false;
  if (!Array.isArray(inputs.stages)) return false;
  if (!Array.isArray(inputs.sectorProfiles)) return false;
  if (!Array.isArray(inputs.allocations)) return false;
  return true;
}

export function buildInvestmentStrategy(inputs: StrategyInputs): InvestmentStrategy {
  // Performance profiling instrumentation
  if (import.meta.env.DEV) {
    performance.mark('strategy:start');
  }

  // Guard against malformed inputs
  if (!validateInputs(inputs)) {
    if (import.meta.env.DEV) {
      performance.mark('strategy:end');
      performance.measure('strategy', 'strategy:start', 'strategy:end');
    }
    return {
      stages: [],
      sectorProfiles: [],
      allocations: [],
      totalSectorAllocation: 0,
      totalAllocation: 0,
      validation: { stages: [], sectors: [], allocations: [], allValid: false }
    };
  }

  // Pure computation - no side effects
  const stages = inputs.stages.map(s => ({
    id: s.id,
    name: s.name,
    graduationRate: s.graduate,
    exitRate: s.exit,
    remainRate: Math.max(0, 100 - s.graduate - s.exit)
  }));

  const sectorProfiles = inputs.sectorProfiles.map(sp => ({ ...sp }));
  const allocations = inputs.allocations.map(a => ({ ...a }));

  // Calculate totals
  const totalSectorAllocation = sectorProfiles.reduce((sum: any, sector: any) => sum + sector.targetPercentage, 0);
  const totalAllocation = allocations.reduce((sum: any, alloc: any) => sum + alloc.percentage, 0);

  // Validation
  const stageValidation = stages.map((stage: any, i: any) => {
    if (!stage.name?.trim()) return 'Stage name required';
    if (stage.graduationRate + stage.exitRate > 100) return 'Graduate + Exit must be ≤ 100%';
    if (i === stages.length - 1 && stage.graduationRate !== 0) return 'Last stage must have 0% graduation';
    return null;
  });

  const sectorValidation = sectorProfiles.map(sector => {
    if (!sector.name?.trim()) return 'Sector name required';
    if (sector.targetPercentage < 0 || sector.targetPercentage > 100) return 'Invalid percentage';
    return null;
  });

  const allocationValidation = allocations.map(allocation => {
    if (!allocation.category?.trim()) return 'Category required';
    if (allocation.percentage < 0 || allocation.percentage > 100) return 'Invalid percentage';
    return null;
  });

  const allValid = [...stageValidation, ...sectorValidation, ...allocationValidation].every(e => !e);

  // Performance profiling end mark
  if (import.meta.env.DEV) {
    performance.mark('strategy:end');
    performance.measure('strategy', 'strategy:start', 'strategy:end');
  }

  return {
    stages,
    sectorProfiles,
    allocations,
    totalSectorAllocation,
    totalAllocation,
    validation: {
      stages: stageValidation,
      sectors: sectorValidation,
      allocations: allocationValidation,
      allValid
    }
  };
}






