});

// Helper to select the right histogram
function getHistogram(name: string): client.Histogram | null {
  switch (name.toUpperCase()) {
    case 'LCP': return webVitalsLCP;
    case 'INP': return webVitalsINP;
    case 'CLS': return webVitalsCLS;
