  distributions: z.number().nonnegative()
    .describe('Cash distributed to LPs this period'),

  unrealizedPnl: z.number()
    .describe('Mark-to-market gains/losses (can be negative)'),

  // Ending balances
  nav: z.number().nonnegative()
